import { db } from "@/lib/db";
import { getSession } from "@/lib/auth-session";
import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";

export default async function TemplateEditorPage({
  params
}: {
  params: Promise<{ institute: string; courseId: string; templateId: string }>;
}) {
  const { institute, courseId, templateId } = await params;
  const isNew = templateId === "new";

  let template: any = null;
  if (!isNew) {
    template = await db.activityTemplate.findUnique({
      where: { id: templateId }
    });
    if (!template) {
      redirect(`/${institute}/courses/${courseId}/activities/instructor`);
    }
  }

  async function saveTemplate(formData: FormData) {
    "use server";
    const session = await getSession();
    if (!session) throw new Error("Unauthorized");

    const title = formData.get("title") as string;
    const activityType = formData.get("activityType") as string;
    const difficulty = parseInt(formData.get("difficulty") as string, 10);
    const variablesStr = formData.get("variables") as string;
    const faultPoolStr = formData.get("faultPool") as string;
    const hiddenTestCasesStr = formData.get("hiddenTestCases") as string;

    // Validate JSON
    try {
      if (variablesStr) JSON.parse(variablesStr);
      if (faultPoolStr) JSON.parse(faultPoolStr);
      if (hiddenTestCasesStr) JSON.parse(hiddenTestCasesStr);
    } catch (e) {
      throw new Error("Invalid JSON in configuration fields.");
    }

    if (isNew) {
      // 1. Create SyllabusItem
      const syllabusItem = await db.syllabusItem.create({
        data: {
          courseId,
          type: "ASSIGNMENT",
          title: `Interactive Activity: ${title}`,
          maxPoints: 100
        }
      });

      // 2. Create Template
      await db.activityTemplate.create({
        data: {
          title,
          activityType,
          courseId,
          syllabusItemId: syllabusItem.id,
          difficulty,
          variables: variablesStr || "{}",
          faultPool: faultPoolStr || "[]",
          hiddenTestCases: hiddenTestCasesStr || "[]",
          createdBy: session.user.id
        }
      });
    } else {
      await db.activityTemplate.update({
        where: { id: templateId },
        data: {
          title,
          activityType,
          difficulty,
          variables: variablesStr || "{}",
          faultPool: faultPoolStr || "[]",
          hiddenTestCases: hiddenTestCasesStr || "[]",
        }
      });

      // Refetch to avoid closure serialization issues with the outer template object
      const existingTemplate = await db.activityTemplate.findUnique({
        where: { id: templateId },
        select: { syllabusItemId: true }
      });

      // Optionally update the linked SyllabusItem title
      if (existingTemplate?.syllabusItemId) {
        await db.syllabusItem.update({
          where: { id: existingTemplate.syllabusItemId },
          data: { title: `Interactive Activity: ${title}` }
        });
      }
    }

    revalidatePath(`/${institute}/courses/${courseId}/activities/instructor`);
    redirect(`/${institute}/courses/${courseId}/activities/instructor`);
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-slate-900 dark:text-[#F0F2F8]">{isNew ? "Create New Scenario" : "Edit Scenario"}</h2>
        <p className="text-xs text-slate-500 dark:text-[#8B92A5] mt-0.5">Define the problem variables, hidden test cases, or faults.</p>
      </div>

      <form action={saveTemplate} className="bg-white dark:bg-[#141721] p-6 rounded-2xl border border-slate-200/80 dark:border-white/5 shadow-xs space-y-6">
        
        <div className="grid grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="font-semibold text-xs text-slate-700 dark:text-[#F0F2F8]">Title</label>
            <input 
              name="title" 
              defaultValue={template?.title || ""} 
              required
              className="w-full rounded-xl border border-slate-200 dark:border-[#3D4460] bg-white dark:bg-[#1E2132] px-3 py-2 text-xs font-medium text-slate-900 dark:text-[#F0F2F8] outline-none transition placeholder:text-slate-400 focus:border-orange-500" 
            />
          </div>
          <div className="space-y-2">
            <label className="font-semibold text-xs text-slate-700 dark:text-[#F0F2F8]">Activity Type</label>
            <select 
              name="activityType" 
              defaultValue={template?.activityType || "codelab"}
              className="w-full rounded-xl border border-slate-200 dark:border-[#3D4460] bg-white dark:bg-[#1E2132] px-3 py-2 text-xs font-medium text-slate-900 dark:text-[#F0F2F8] outline-none transition focus:border-orange-500"
            >
              <option value="codelab">CodeLab</option>
              <option value="pc-build">PC Build</option>
              <option value="arduino">Arduino</option>
              <option value="server-rack">Server Rack</option>
              <option value="logic-gate">Logic Gates</option>
            </select>
          </div>
        </div>

        <div className="space-y-2">
          <label className="font-semibold text-xs text-slate-700 dark:text-[#F0F2F8]">Difficulty Level</label>
          <div className="flex gap-4">
            {[1, 2, 3].map(level => (
              <label key={level} className="flex items-center gap-2 text-xs font-medium text-slate-700 dark:text-[#F0F2F8]">
                <input 
                  type="radio" 
                  name="difficulty" 
                  value={level} 
                  defaultChecked={(template?.difficulty || 1) === level} 
                  className="accent-[#F97316]"
                />
                Level {level}
              </label>
            ))}
          </div>
        </div>

        <div className="space-y-2">
          <label className="font-semibold text-xs text-slate-700 dark:text-[#F0F2F8]">Variables (JSON Object)</label>
          <p className="text-[11px] text-slate-400 dark:text-[#8B92A5]">e.g., CodeLab variables or Arduino thresholds.</p>
          <textarea 
            name="variables" 
            defaultValue={template?.variables || "{}"}
            rows={5}
            className="w-full font-mono text-xs rounded-xl border border-slate-200 dark:border-[#3D4460] bg-slate-50/50 dark:bg-[#1E2132] p-3 text-slate-900 dark:text-[#F0F2F8] outline-none transition placeholder:text-slate-400 focus:border-orange-500"
          />
        </div>

        <div className="grid grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="font-semibold text-xs text-slate-700 dark:text-[#F0F2F8]">Fault Pool (JSON Array)</label>
            <p className="text-[11px] text-slate-400 dark:text-[#8B92A5]">For 3D troubleshooting scenarios.</p>
            <textarea 
              name="faultPool" 
              defaultValue={template?.faultPool || "[]"}
              rows={5}
              className="w-full font-mono text-xs rounded-xl border border-slate-200 dark:border-[#3D4460] bg-slate-50/50 dark:bg-[#1E2132] p-3 text-slate-900 dark:text-[#F0F2F8] outline-none transition placeholder:text-slate-400 focus:border-orange-500"
            />
          </div>

          <div className="space-y-2">
            <label className="font-semibold text-xs text-slate-700 dark:text-[#F0F2F8]">Hidden Test Cases (JSON Array)</label>
            <p className="text-[11px] text-slate-400 dark:text-[#8B92A5]">For CodeLab grading.</p>
            <textarea 
              name="hiddenTestCases" 
              defaultValue={template?.hiddenTestCases || "[]"}
              rows={5}
              className="w-full font-mono text-xs rounded-xl border border-slate-200 dark:border-[#3D4460] bg-slate-50/50 dark:bg-[#1E2132] p-3 text-slate-900 dark:text-[#F0F2F8] outline-none transition placeholder:text-slate-400 focus:border-orange-500"
            />
          </div>
        </div>

        <div className="flex justify-end pt-4 border-t border-slate-100 dark:border-white/5">
          <button 
            type="submit" 
            className="bg-[#F97316] hover:bg-orange-600 text-white font-semibold text-xs py-2 px-6 rounded-xl transition-colors cursor-pointer shadow-xs"
          >
            Save Template
          </button>
        </div>
      </form>
    </div>
  );
}

/**
 * Instructor Logic Gate Activity Template Editor
 * Route: /[institute]/courses/[courseId]/activities/logic-gate/new
 */

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { db } from "@/lib/db";
import { getSession } from "@/lib/auth-session";
import { getInstituteTheme } from "@/lib/get-institute-theme";

const createTemplateSchema = z.object({
  courseId: z.string(),
  difficulty: z.coerce.number().min(1).max(3),
  faultPool: z.array(z.string()),
  targetTruthTable: z.string().optional(),
});

export default async function NewLogicGateActivityPage({
  params,
}: {
  params: Promise<{ institute: string; courseId: string }>;
}) {
  const { institute, courseId } = await params;
  const session = await getSession();
  const theme = getInstituteTheme(institute);

  if (!session || (session.user.role !== "INSTRUCTOR" && session.user.role !== "PROFESSOR" && session.user.role !== "ADMIN")) {
    redirect(`/${institute}/courses/${courseId}`);
  }

  async function createTemplate(formData: FormData) {
    "use strict";
    "use server";
    const sessionInfo = await getSession();
    if (!sessionInfo) throw new Error("Unauthorized");

    const faults = formData.getAll("faultPool") as string[];
    const difficulty = formData.get("difficulty") as string;
    const targetTruthTableStr = formData.get("targetTruthTable") as string;
    
    let parsedTable = null;
    if (targetTruthTableStr && targetTruthTableStr.trim().length > 0) {
      try {
        parsedTable = JSON.parse(targetTruthTableStr);
      } catch (e) {
        throw new Error("Invalid JSON for Target Truth Table");
      }
    }

    const parsed = createTemplateSchema.safeParse({
      courseId,
      difficulty: parseInt(difficulty, 10),
      faultPool: faults,
      targetTruthTable: targetTruthTableStr,
    });

    if (!parsed.success) {
      throw new Error("Validation failed");
    }

    const { data } = parsed;

    const template = await db.activityTemplate.create({
      data: {
        activityType: "logic-gate", 
        courseId: data.courseId,
        difficulty: data.difficulty,
        faultPool: JSON.stringify(data.faultPool),
        variables: JSON.stringify({ targetTruthTable: parsedTable }),
        createdBy: sessionInfo.user.id,
      },
    });

    revalidatePath(`/${institute}/courses/${courseId}`);
    redirect(`/${institute}/courses/${courseId}?createdTemplateId=${template.id}`);
  }

  const availableFaults = [
    { id: "SWAPPED_GATE_OR_TO_XOR", label: "Troubleshooting: Pre-built circuit uses XOR instead of OR" },
    { id: "MISWIRED_INPUT", label: "Troubleshooting: Input B is wired to wrong gate" },
  ];

  const defaultTruthTable = `{
  "inputs": ["inA", "inB"],
  "outputs": ["outY"],
  "rows": [
    {"in": [false, false], "out": [false]},
    {"in": [false, true], "out": [true]},
    {"in": [true, false], "out": [true]},
    {"in": [true, true], "out": [true]}
  ]
}`;

  return (
    <div className="max-w-3xl mx-auto p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900 dark:text-[#F0F2F8]">Create Logic Gate Assignment</h1>
        <p className="text-xs text-slate-500 dark:text-[#8B92A5] mt-1">
          Configure a combinational logic or troubleshooting lab.
        </p>
      </div>

      <form action={createTemplate} className="space-y-8 bg-white dark:bg-[#141721] p-6 rounded-2xl border border-slate-200/80 dark:border-white/5 shadow-xs">
        
        <div className="space-y-4">
          <h2 className="text-sm font-bold text-slate-900 dark:text-[#F0F2F8] border-b border-slate-100 dark:border-white/5 pb-2">Assignment Type</h2>
          <div className="flex gap-6">
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="radio" name="difficulty" value="1" defaultChecked className="accent-[#F97316]" />
              <span className="text-xs font-semibold text-slate-700 dark:text-[#F0F2F8]">Build Mode (Match Truth Table)</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="radio" name="difficulty" value="2" className="accent-[#F97316]" />
              <span className="text-xs font-semibold text-slate-700 dark:text-[#F0F2F8]">Troubleshooting Mode (Fix Broken Circuit)</span>
            </label>
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-sm font-bold text-slate-900 dark:text-[#F0F2F8] border-b border-slate-100 dark:border-white/5 pb-2">Troubleshooting Faults (If Applicable)</h2>
          <div className="space-y-3">
            {availableFaults.map((fault) => (
              <label key={fault.id} className="flex items-start gap-3 cursor-pointer p-3 rounded-xl border border-slate-200/60 dark:border-white/5 hover:bg-slate-50/50 dark:hover:bg-white/[0.02] transition-colors">
                <input type="checkbox" name="faultPool" value={fault.id} className="mt-1 accent-[#F97316]" />
                <div>
                  <span className="block text-xs font-semibold text-slate-900 dark:text-[#F0F2F8]">{fault.label}</span>
                </div>
              </label>
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-sm font-bold text-slate-900 dark:text-[#F0F2F8] border-b border-slate-100 dark:border-white/5 pb-2">Target Truth Table (JSON)</h2>
          <p className="text-xs text-slate-400 dark:text-[#8B92A5]">Leave blank for a free-build sandbox. Provide JSON to auto-grade combinational logic.</p>
          <textarea 
            name="targetTruthTable" 
            defaultValue={defaultTruthTable}
            rows={10}
            className="w-full font-mono text-xs p-4 bg-slate-50/50 dark:bg-[#1E2132] border border-slate-200 dark:border-[#3D4460] rounded-xl text-slate-900 dark:text-[#F0F2F8] focus:border-orange-500 outline-none"
          />
        </div>

        <div className="pt-4 flex justify-end">
          <button 
            type="submit"
            className="px-6 py-2.5 rounded-xl text-white text-xs font-semibold transition-colors cursor-pointer shadow-xs"
            style={{ backgroundColor: theme.colors.primary }}
          >
            Create Assignment Template
          </button>
        </div>
      </form>
    </div>
  );
}

