            </label>
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-sm font-bold text-slate-900 dark:text-[#F0F2F8] border-b border-slate-100 dark:border-white/5 pb-2">Eligible Faults Pool</h2>
          <p className="text-xs text-slate-500 dark:text-[#8B92A5]">
            Select the faults that the system can randomly inject. The system will pick up to [Difficulty] faults from this pool per student.
          </p>
          <div className="space-y-3">
            {availableFaults.map((fault) => (
              <label key={fault.id} className="flex items-start gap-3 cursor-pointer p-3 rounded-xl border border-slate-200/60 dark:border-white/5 hover:bg-slate-50/50 dark:hover:bg-white/[0.02] transition-colors">
                <input 
                  type="checkbox" 
                  name="faultPool" 
                  value={fault.id} 
                  defaultChecked
                  className="mt-1 accent-[#F97316]"
                />
                <div>
                  <span className="block text-xs font-semibold text-slate-900 dark:text-[#F0F2F8]">{fault.label}</span>
                  <span className="block text-[10px] text-slate-400 dark:text-[#8B92A5] font-mono mt-0.5">{fault.id}</span>
                </div>
              </label>
            ))}
          </div>
        </div>

        <div className="pt-4 flex justify-end">
          <button 
            type="submit"
            className="px-6 py-2.5 rounded-xl text-white text-xs font-semibold transition-colors cursor-pointer shadow-xs"
            style={{ backgroundColor: theme.colors.primary }}
          >
            Create Assignment Template
          </button>
        </div>
      </form>
    </div>
  );
}

/**
 * Instructor Server Rack Activity Template Editor
 * Route: /[institute]/courses/[courseId]/activities/server-rack/new
 */

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { db } from "@/lib/db";
import { getSession } from "@/lib/auth-session";
import { getInstituteTheme } from "@/lib/get-institute-theme";

const createTemplateSchema = z.object({
  courseId: z.string(),
  difficulty: z.coerce.number().min(1).max(3),
  faultPool: z.array(z.string()),
  goalDescription: z.string(),
});

export default async function NewServerRackActivityPage({
  params,
}: {
  params: Promise<{ institute: string; courseId: string }>;
}) {
  const { institute, courseId } = await params;
  const session = await getSession();
  const theme = getInstituteTheme(institute);

  if (!session || (session.user.role !== "INSTRUCTOR" && session.user.role !== "PROFESSOR" && session.user.role !== "ADMIN")) {
    redirect(`/${institute}/courses/${courseId}`);
  }

  async function createTemplate(formData: FormData) {
    "use strict";
    "use server";
    const sessionInfo = await getSession();
    if (!sessionInfo) throw new Error("Unauthorized");

    const faults = formData.getAll("faultPool") as string[];
    const difficulty = formData.get("difficulty") as string;
    const goalDescription = formData.get("goalDescription") as string;

    const parsed = createTemplateSchema.safeParse({
      courseId,
      difficulty: parseInt(difficulty, 10),
      faultPool: faults,
      goalDescription,
    });

    if (!parsed.success) {
      throw new Error("Validation failed");
    }

    const { data } = parsed;

    const template = await db.activityTemplate.create({
      data: {
        activityType: "server-rack", 
        courseId: data.courseId,
        difficulty: data.difficulty,
        faultPool: JSON.stringify(data.faultPool),
        variables: JSON.stringify({ goalDescription: data.goalDescription }),
        createdBy: sessionInfo.user.id,
      },
    });

    revalidatePath(`/${institute}/courses/${courseId}`);
    redirect(`/${institute}/courses/${courseId}?createdTemplateId=${template.id}`);
  }

  const availableFaults = [
    { id: "WRONG_SUBNET_MASK", label: "Server pre-configured with incorrect subnet mask" },
    { id: "MISWIRED_T568A", label: "Uplink cable terminated as T568A instead of B (Simulation only)" },
  ];

  const defaultGoal = `1. Rack mount the Patch Panel, Switch, and both Servers.
2. Connect Server 1 and Server 2 to the Patch Panel, and patch them into the Switch using T568B cables.
3. Configure both servers to be on the 192.168.1.0/24 subnet.
4. Successfully ping Server 2 from Server 1.`;

  return (
    <div className="max-w-3xl mx-auto p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900 dark:text-[#F0F2F8]">Create Networking Assignment</h1>
        <p className="text-xs text-slate-500 dark:text-[#8B92A5] mt-1">
          Configure a server rack patching and subnetting lab.
        </p>
      </div>

      <form action={createTemplate} className="space-y-8 bg-white dark:bg-[#141721] p-6 rounded-2xl border border-slate-200/80 dark:border-white/5 shadow-xs">
        
        <div className="space-y-4">
          <h2 className="text-sm font-bold text-slate-900 dark:text-[#F0F2F8] border-b border-slate-100 dark:border-white/5 pb-2">Difficulty</h2>
          <div className="flex gap-6">
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="radio" name="difficulty" value="1" defaultChecked className="accent-[#F97316]" />
              <span className="text-xs font-semibold text-slate-700 dark:text-[#F0F2F8]">Beginner (1 Fault)</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="radio" name="difficulty" value="2" className="accent-[#F97316]" />
              <span className="text-xs font-semibold text-slate-700 dark:text-[#F0F2F8]">Intermediate (2 Faults)</span>
            </label>
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-sm font-bold text-slate-900 dark:text-[#F0F2F8] border-b border-slate-100 dark:border-white/5 pb-2">Eligible Faults Pool</h2>
          <div className="space-y-3">
            {availableFaults.map((fault) => (
              <label key={fault.id} className="flex items-start gap-3 cursor-pointer p-3 rounded-xl border border-slate-200/60 dark:border-white/5 hover:bg-slate-50/50 dark:hover:bg-white/[0.02] transition-colors">
                <input type="checkbox" name="faultPool" value={fault.id} defaultChecked className="mt-1 accent-[#F97316]" />
                <div>
                  <span className="block text-xs font-semibold text-slate-900 dark:text-[#F0F2F8]">{fault.label}</span>
                </div>
              </label>
            ))}
          </div>
        </div>

        <div className="space-y-4">
          <h2 className="text-sm font-bold text-slate-900 dark:text-[#F0F2F8] border-b border-slate-100 dark:border-white/5 pb-2">Goal Description</h2>
          <textarea 
            name="goalDescription" 
            defaultValue={defaultGoal}
            rows={5}
            className="w-full text-xs p-4 bg-slate-50/50 dark:bg-[#1E2132] border border-slate-200 dark:border-[#3D4460] rounded-xl text-slate-900 dark:text-[#F0F2F8] focus:border-orange-500 outline-none"
          />
        </div>

        <div className="pt-4 flex justify-end">
          <button 
            type="submit"
            className="px-6 py-2.5 rounded-xl text-white text-xs font-semibold transition-colors cursor-pointer shadow-xs"
            style={{ backgroundColor: theme.colors.primary }}
          >
            Create Assignment Template
          </button>
        </div>
      </form>
    </div>
  );
}

import { db } from "@/lib/db";
import { getInstituteTheme } from "@/lib/get-institute-theme";
import { getSession } from "@/lib/auth-session";
import { redirect } from "next/navigation";
import CourseHeader from "@/components/courses/CourseHeader";
import CourseTabs from "@/components/courses/CourseTabs";

type LayoutProps = {
  children: React.ReactNode;
  params: Promise<{ institute: string; courseId: string }>;
};

export default async function CourseInteriorLayout({
  children,
  params,
}: LayoutProps) {
  const { institute, courseId } = await params;
  const session = await getSession();

  if (!session) {
    redirect(`/login?institute=${institute}`);
  }

  const theme = getInstituteTheme(institute);

  const course = await db.course.findUnique({
    where: { id: courseId },
    include: {
      instructor: { select: { name: true } },
      _count: {
        select: {
          enrollments: { where: { status: "PENDING" } },
        },
      },
    },
  });

  if (!course) {
    redirect(`/${institute}/courses`);
  }

  // Access control: user must be instructor, enrolled student, or admin
  const userRole = session.user.role.toUpperCase();
  const isInstructor = course.instructorId === session.user.id;
  const isAdmin = userRole === "ADMIN";

  if (!isInstructor && !isAdmin) {
    // Check if student is enrolled
    const enrollment = await db.enrollment.findUnique({
      where: {
        courseId_studentId: {
          courseId: course.id,
          studentId: session.user.id,
        },
      },
    });

    if (!enrollment || enrollment.status !== "APPROVED") {
      redirect(`/${institute}/courses`);
    }
  }

  const showPendingCount =
    isInstructor || isAdmin ? course._count.enrollments : 0;

  const pendingWorkCount =
    isInstructor || isAdmin
      ? await db.studentSubmission.count({
          where: {
            syllabusItem: { courseId: course.id },
            status: "SUBMITTED",
            OR: [{ grade: null }, { isReturned: false }],
          },
        })
      : 0;

  return (
    <div className="-m-4 lg:-m-8">
      <div className="px-4 pt-4 md:px-8 md:pt-6">
        <CourseHeader
          course={course}
          theme={theme}
          pendingWorkCount={pendingWorkCount}
          isInstructor={isInstructor || isAdmin}
          instituteCode={institute}
          courseId={courseId}
        />
      </div>
      <div className="mt-4">
        <CourseTabs
          courseId={courseId}
          instituteCode={institute}
          theme={theme}
          pendingCount={showPendingCount}
          pendingWorkCount={pendingWorkCount}
          isInstructor={isInstructor || isAdmin}
        />
      </div>
      <div className="px-4 py-6 md:px-8">{children}</div>
    </div>
  );
}

import { redirect } from "next/navigation";
import { getSession } from "@/lib/auth-session";
import { getInstituteTheme } from "@/lib/get-institute-theme";
import { isEligibleForActivities } from "@/lib/activity-eligibility";
import { isEligibleForKnowledgeExchange } from "@/lib/kx-eligibility";
import { db } from "@/lib/db";
import { processLoginReward } from "@/lib/gamification/login-rewards";
import DashboardLayout from "@/components/layout/DashboardLayout";

export const dynamic = "force-dynamic";

export default async function InstituteLayout({ 
  children, 
  params 
}: { 
  children: React.ReactNode,
  params: Promise<{ institute: string }>
}) {
  const { institute } = await params;
  const session = await getSession();

  if (!session) {
    redirect(`/login?institute=${institute}`);
  }

  // Enforce institute scoping: students and teachers are strictly locked to their registered institute.
  // Admins are system administrators who can view, switch, and manage any institute campus.
  const userRole = ((session.user as Record<string, unknown>).role as string || "").toUpperCase();
  const isAdmin = userRole === "ADMIN";

  let userInstituteCode = "ics";
  if (session.user.instituteId) {
    const userInstitute = await db.institute.findUnique({
      where: { id: session.user.instituteId },
      select: { code: true },
    });
    if (userInstitute?.code) {
      userInstituteCode = userInstitute.code.toLowerCase();
    }
  }

  if (!isAdmin && userInstituteCode !== institute.toLowerCase()) {
    redirect(`/${userInstituteCode}`);
  }

  const theme = getInstituteTheme(institute);

  // Compute activity eligibility for the sidebar
  const activityEligible = await isEligibleForActivities({
    user: {
      id: session.user.id,
      role: session.user.role as string,
      instituteId: session.user.instituteId as string,
    },
  });

  // Compute Knowledge Exchange eligibility for the sidebar
  const isKxSessionEligible = await isEligibleForKnowledgeExchange({
    user: {
      id: session.user.id,
      role: session.user.role as string,
      instituteId: session.user.instituteId as string,
    },
  });
  const kxEligible = institute.toLowerCase() === "ics" && isKxSessionEligible;

  const role = (session.user.role as string).toUpperCase();
  const isStudent = role === "STUDENT";
  const isProfessor = role === "PROFESSOR" || role === "TEACHER";
  let enrolledCourses: { id: string; title: string; code: string }[] = [];

  const instituteRecord = await db.institute.findUnique({
    where: { code: institute.toLowerCase() },
    select: { id: true },
  });

  if (instituteRecord) {
    if (isStudent) {
      const enrollments = await db.enrollment.findMany({
        where: {
          studentId: session.user.id,
          status: "APPROVED",
          course: {
            instituteId: instituteRecord.id,
            isArchived: false,
          },
        },
        select: {
          course: {
            select: {
              id: true,
              title: true,
              code: true,
            },
          },
        },
        orderBy: { displayOrderIndex: "asc" },
      });

      enrolledCourses = enrollments.map((e) => e.course);
    } else if (isProfessor) {
      const taught = await db.course.findMany({
        where: {
          instructorId: session.user.id,
          instituteId: instituteRecord.id,
          isArchived: false,
        },
        select: {
          id: true,
          title: true,
          code: true,
        },
        orderBy: { code: "asc" },
      });

      enrolledCourses = taught;
    }
  }

  // Process daily login reward for student (increments streak & awards EXP on new day)
  if (session.user.role === "STUDENT") {
    try {
      await processLoginReward(session.user.id);
    } catch (err) {
      console.error("Failed to process login reward on layout load:", err);
    }
  }

  // Fetch gamification profile for user (level badge in topbar & streak modal)
  let gamification = await db.gamificationProfile.findUnique({
    where: { studentId: session.user.id },
    select: { exp: true, loginStreakCurrent: true },
  });

  return (
    <DashboardLayout
      instituteCode={theme.code}
      instituteName={theme.name}
      userName={session.user.name as string}
      userRole={session.user.role as string}
      studentNumber={(session.user.studentNumber as string | undefined) || null}
      avatarUrl={(session.user as Record<string, unknown>).avatarUrl as string | null ?? null}
      theme={theme}
      isEligibleForActivities={activityEligible}
      isEligibleForKnowledgeExchange={kxEligible}
      enrolledCourses={enrolledCourses}
      exp={gamification?.exp || 0}
      streakCurrent={gamification?.loginStreakCurrent || 1}
      userId={session.user.id}
    >
      {children}
    </DashboardLayout>
  );
}

import { redirect } from "next/navigation";
import { getSession } from "@/lib/auth-session";

type PageProps = {
  params: Promise<{
    institute: string;
  }>;
};

export default async function InstituteDashboardPage({ params }: PageProps) {
  const { institute } = await params;
  const session = await getSession();

  if (!session) {
    redirect(`/login?institute=${institute}`);
  }

  const role = session.user.role.toUpperCase();

  if (role === "STUDENT") {
    redirect(`/${institute}/students`);
  } else if (role === "PROFESSOR" || role === "TEACHER") {
    redirect(`/${institute}/teachers`);
  } else if (role === "ADMIN") {
    redirect(`/${institute}/admin`);
  }

  // Fallback if role is unknown
  return <div>Unknown role</div>;
}

