"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import Input from "@/components/common/Input";
import Button from "@/components/common/Button";
import { isDesktopAdmin as isDesktopAdminCheck } from "@/lib/electron-detect";
import { triggerNativeHaptic, syncSessionToNative } from "@/lib/mobile-bridge";
import type { InstituteTheme } from "@/lib/theme";

type LoginFormValues = {
  email: string;
  password: string;
};

type LoginFormProps = {
  theme: InstituteTheme;
  instituteCode: string;
  isDesktopAdmin?: boolean;
};

export default function LoginForm({
  theme,
  instituteCode,
  isDesktopAdmin = false,
}: LoginFormProps) {
  const router = useRouter();

  const [isDesktopMode, setIsDesktopMode] = useState<boolean>(isDesktopAdmin);

  useEffect(() => {
    if (
      !isDesktopMode &&
      (isDesktopAdmin ||
        isDesktopAdminCheck() ||
        new URLSearchParams(window.location.search).get("desktop") === "admin" ||
        (typeof navigator !== "undefined" && navigator.userAgent.includes("Electron")))
    ) {
      setIsDesktopMode(true);
    }
  }, [isDesktopAdmin, isDesktopMode]);

  const [values, setValues] = useState<LoginFormValues>({
    email: "",
    password: "",
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string>("");

  function updateField<K extends keyof LoginFormValues>(
    key: K,
    value: LoginFormValues[K]
  ) {
    setValues((prev) => ({
      ...prev,
      [key]: value,
    }));
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setErrorMessage("");
    setIsSubmitting(true);

    try {
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ...values,
          instituteCode,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || "Unable to sign in.");
      }

      triggerNativeHaptic("success");
      if (data.token) {
        syncSessionToNative(data.token, data.user);
      }

      const role = data.user.role.toUpperCase();

      if (isDesktopMode && role !== "ADMIN") {
        setErrorMessage(
          "This application is restricted to administrators only. Students and instructors should use the web portal or mobile app."
        );
        await fetch("/api/auth/logout", { method: "POST" });
        return;
      }

      let targetPath = `/${data.user.institute.code}`;

      if (isDesktopMode || role === "ADMIN") {
        targetPath += "/admin";
      } else if (role === "STUDENT") {
        targetPath += "/students";
      } else if (role === "PROFESSOR" || role === "TEACHER") {
        targetPath += "/teachers";
      }

      window.location.href = targetPath;
    } catch (error) {
      triggerNativeHaptic("error");
      setErrorMessage(
        error instanceof Error ? error.message : "Unable to sign in."
      );
    } finally {
      setIsSubmitting(false);
    }
  }

  const registerLink = isDesktopMode
    ? `/register?institute=${instituteCode}&desktop=admin`
    : `/register?institute=${instituteCode}`;

  return (
    <form onSubmit={handleSubmit} className="grid gap-4">
      <Input
        id="email"
        name="email"
        label="Email"
        type="email"
        placeholder={isDesktopMode ? "admin@school.edu" : "student@school.edu"}
        value={values.email}
        onChange={(event) => updateField("email", event.target.value)}
        theme={theme}
        required
      />

      <div className="grid gap-1">
        <Input
          id="password"
          name="password"
          label="Password"
          type="password"
          placeholder="Enter your password"
          value={values.password}
          onChange={(event) => updateField("password", event.target.value)}
          theme={theme}
          required
        />
        <div className="flex justify-end mt-1">
          <Link
            href={`/forgot-password?institute=${instituteCode}`}
            className="text-xs font-medium hover:underline"
            style={{ color: theme.colors.primary }}
          >
            Forgot Password?
          </Link>
        </div>
      </div>

      {errorMessage ? (
        <p className="text-sm font-medium text-red-600">{errorMessage}</p>
      ) : null}

      <Button type="submit" theme={theme} disabled={isSubmitting}>
        {isSubmitting ? "Signing In..." : "Sign In"}
      </Button>

      <div className="flex items-center justify-between gap-3 text-sm text-gray-600">
        <span>{isDesktopMode ? "New Administrator?" : "New to CdM LMS?"}</span>
        <Link
          href={registerLink}
          className="font-medium hover:underline"
          style={{ color: theme.colors.primary }}
        >
          {isDesktopMode ? "Register Administrator" : "Create an account"}
        </Link>
      </div>
    </form>
  );
}

apps/web/src/components/layout/Dashboard.content:
"use client";

import { Suspense, useState } from "react";
import Sidebar from "@/components/layout/Sidebar";
import type { EnrolledCourseSummary } from "@/components/layout/Sidebar";
import Topbar from "@/components/layout/Topbar";
import NavigationProgress from "@/components/layout/NavigationProgress";
import Toaster from "@/components/common/Toast";
import { AvatarProvider } from "@/lib/avatar-context";
import { ThemeProvider } from "@/lib/theme-context";
import { ChatbotProvider } from "@/lib/chatbot-context";
import ChatbotWidget from "@/components/common/ChatbotWidget";
import BadgeToastProvider from "@/components/common/BadgeToast";
import LoginRewardModal from "@/components/common/LoginRewardModal";
import FloatingStudyTimer from "@/components/common/FloatingStudyTimer";
import MobileBottomNav from "@/components/layout/MobileBottomNav";
import type { InstituteTheme } from "@/lib/theme";

interface DashboardLayoutProps {
  instituteCode: string;
  instituteName: string;
  userName: string;
  userRole: string;
  studentNumber?: string | null;
  avatarUrl?: string | null;
  theme: InstituteTheme;
  /** Whether this user qualifies for ICS Interactive Activities. Controls sidebar entry visibility. */
  isEligibleForActivities?: boolean;
  /** Whether this user qualifies for Knowledge Exchange. Controls sidebar entry visibility. */
  isEligibleForKnowledgeExchange?: boolean;
  /** Enrolled courses for student sidebar accordion. */
  enrolledCourses?: EnrolledCourseSummary[];
  /** Gamification total EXP for LevelBadge */
  exp?: number;
  /** Current login streak */
  streakCurrent?: number;
  userId?: string;
  children: React.ReactNode;
}

export default function DashboardLayout({
  instituteCode,
  instituteName,
  userName,
  userRole,
  studentNumber,
  avatarUrl,
  theme,
  isEligibleForActivities,
  isEligibleForKnowledgeExchange,
  enrolledCourses,
  exp = 0,
  streakCurrent = 0,
  userId,
  children,
}: DashboardLayoutProps) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  const isStudent = userRole.toUpperCase() === "STUDENT";

  const layoutContent = (
    <div
      className="min-h-[100dvh] bg-canvas text-primary-theme transition-colors duration-200 overflow-x-clip max-w-full"
      style={{
        "--focus-ring": theme.colors.primary,
      } as React.CSSProperties}
    >
      {/* Navigation Progress Bar */}
      <Suspense fallback={null}>
        <NavigationProgress color={theme.colors.primary} />
      </Suspense>

      <div className="flex">
        <Sidebar
          instituteCode={instituteCode}
          theme={theme}
          userRole={userRole}
          isCollapsed={isSidebarCollapsed}
          onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
          isEligibleForActivities={isEligibleForActivities}
          isEligibleForKnowledgeExchange={isEligibleForKnowledgeExchange}
          enrolledCourses={enrolledCourses}
        />

        {/* Mobile Sidebar Drawer (Slides in on burger menu click) */}
        <div
          className={`fixed inset-0 z-[60] lg:hidden transition-all duration-300 ${
            mobileOpen ? "pointer-events-auto opacity-100" : "pointer-events-none opacity-0"
          }`}
          aria-hidden={!mobileOpen}
        >
          {/* Backdrop scrim */}
          <div
            className="absolute inset-0 bg-black/60 backdrop-blur-xs transition-opacity duration-300"
            onClick={() => setMobileOpen(false)}
          />
          {/* Drawer container */}
          <div
            className={`relative z-10 h-full max-w-[280px] w-[80vw] transition-transform duration-300 ease-in-out ${
              mobileOpen ? "translate-x-0" : "-translate-x-full"
            }`}
          >
            <Sidebar
              instituteCode={instituteCode}
              theme={theme}
              userRole={userRole}
              isCollapsed={false}
              isMobileDrawer={true}
              onCloseMobileDrawer={() => setMobileOpen(false)}
              isEligibleForActivities={isEligibleForActivities}
              isEligibleForKnowledgeExchange={isEligibleForKnowledgeExchange}
              enrolledCourses={enrolledCourses}
            />
          </div>
        </div>

        <div className={`min-w-0 flex-1 overflow-x-hidden max-w-full transition-all duration-300 ${
          isSidebarCollapsed ? "lg:pl-[72px]" : "lg:pl-72"
        }`}>
          <Topbar
            theme={theme}
            instituteName={instituteName}
            userName={userName}
            userRole={userRole}
            studentNumber={studentNumber}
            avatarUrl={avatarUrl ?? null}
            instituteCode={instituteCode}
            exp={exp}
            onOpenMobileMenu={() => setMobileOpen(true)}
          />
          <main className="px-4 py-4 lg:px-8 lg:py-8 pb-[calc(120px+env(safe-area-inset-bottom,0px))] lg:pb-8">
            <AvatarProvider initialAvatarUrl={avatarUrl ?? null}>
              {children}
            </AvatarProvider>
          </main>
        </div>
      </div>

      {/* Toast Notifications */}
      <Toaster />

      {/* Mobile Bottom Navigation */}
      <MobileBottomNav
        instituteCode={instituteCode}
        primaryColor={theme.colors.primary}
        userRole={userRole}
        userName={userName}
        avatarUrl={avatarUrl ?? null}
      />

      {/* Gamification Badge Toasts */}
      <BadgeToastProvider />

      {/* Student Gamification Widgets */}
      {isStudent && (
        <>
          <LoginRewardModal
            userId={userId}
            streakCurrent={streakCurrent}
            expEarned={10}
            totalExp={exp}
          />
          <FloatingStudyTimer />
          <ChatbotWidget theme={theme} />
        </>
      )}
    </div>
  );

  return (
    <ThemeProvider>
      {isStudent ? (
        <ChatbotProvider>{layoutContent}</ChatbotProvider>
      ) : (
        layoutContent
      )}
    </ThemeProvider>
  );
}

