"use client";

import { useState, useRef } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { LayoutDashboard, BookOpen, Trophy, Megaphone, MoreHorizontal, BarChart2, Shield } from "lucide-react";
import MobileMoreSheet from "@/components/layout/MobileMoreSheet";

import { triggerNativeHaptic } from "@/lib/mobile-bridge";

interface MobileBottomNavProps {
  instituteCode: string;
  primaryColor: string;
  userRole: string;
  userName?: string;
  avatarUrl?: string | null;
}

export default function MobileBottomNav({
  instituteCode,
  primaryColor,
  userRole,
  userName,
  avatarUrl,
}: MobileBottomNavProps) {
  const pathname = usePathname();
  const [isMoreOpen, setIsMoreOpen] = useState(false);
  const role = userRole.toUpperCase();
  const isStudent = role === "STUDENT";
  const isProfessor = role === "PROFESSOR" || role === "TEACHER";

  const studentTabs = [
    { name: "Dashboard", href: `/${instituteCode}/students`, icon: LayoutDashboard },
    { name: "Courses", href: `/${instituteCode}/courses`, icon: BookOpen },
    { name: "Grades", href: `/${instituteCode}/grades`, icon: Trophy },
    { name: "Alerts", href: `/${instituteCode}/announcements`, icon: Megaphone },
    { name: "More", isMore: true, icon: MoreHorizontal },
  ];

  const teacherTabs = [
    { name: "Dashboard", href: `/${instituteCode}/teachers`, icon: LayoutDashboard },
    { name: "Classes", href: `/${instituteCode}/courses`, icon: BookOpen },
    { name: "Analytics", href: `/${instituteCode}/analytics`, icon: BarChart2 },
    { name: "Alerts", href: `/${instituteCode}/announcements`, icon: Megaphone },
    { name: "More", isMore: true, icon: MoreHorizontal },
  ];

  const adminTabs = [
    { name: "Dashboard", href: `/${instituteCode}/admin`, icon: LayoutDashboard },
    { name: "Courses", href: `/${instituteCode}/admin/courses`, icon: BookOpen },
    { name: "Accounts", href: `/${instituteCode}/accounts`, icon: Trophy },
    { name: "Logs", href: `/${instituteCode}/logs`, icon: Megaphone },
    { name: "More", isMore: true, icon: MoreHorizontal },
  ];

  const tabs = isStudent ? studentTabs : isProfessor ? teacherTabs : adminTabs;

  const lastToggleRef = useRef<number>(0);

  const handleMoreToggle = () => {
    const now = Date.now();
    if (now - lastToggleRef.current < 350) return;
    lastToggleRef.current = now;
    try {
      triggerNativeHaptic("light");
    } catch {}
    setIsMoreOpen((prev) => !prev);
  };

  return (
    <>
      <nav className="fixed bottom-0 left-0 right-0 z-[90] lg:hidden bg-white dark:bg-[#1A1D27] border-t border-slate-200/80 dark:border-white/10 pb-[env(safe-area-inset-bottom)] shadow-lg">
        <div className="flex justify-around items-center min-h-[56px] px-1">
          {tabs.map((tab) => {
            const Icon = tab.icon;

            if (tab.isMore) {
              const isActive = isMoreOpen;
              return (
                <button
                  key={tab.name}
                  id="mobile-nav-more"
                  type="button"
                  onClick={handleMoreToggle}
                  className="flex flex-col items-center justify-center flex-1 min-w-0 max-w-[80px] min-h-[44px] gap-1 py-1.5 px-0.5 active:scale-95 transition-transform cursor-pointer touch-manipulation select-none"
                  style={{ color: isActive ? primaryColor : undefined }}
                  aria-label="Open more navigation options"
                  aria-expanded={isMoreOpen}
                >
                  <Icon
                    className={`w-5 h-5 shrink-0 ${isActive ? "" : "text-slate-500 dark:text-slate-400"}`}
                  />
                  <span
                    className={`text-[10px] font-medium leading-tight truncate w-full text-center tracking-tight ${isActive ? "font-bold" : "text-slate-500 dark:text-slate-400"}`}
                  >
                    {tab.name}
                  </span>
                </button>
              );
            }

            const href = tab.href!;
            const isActive =
              href.endsWith("/courses")
                ? pathname === href || pathname.startsWith(href + "/")
                : pathname === href;

            return (
              <Link
                key={tab.name}
                href={href}
                className="flex flex-col items-center justify-center flex-1 min-w-0 max-w-[80px] min-h-[44px] gap-1 py-1.5 px-0.5 active:scale-95 transition-transform cursor-pointer touch-manipulation select-none"
                style={{ color: isActive ? primaryColor : undefined }}
              >
                <Icon
                  className={`w-5 h-5 shrink-0 ${isActive ? "" : "text-slate-500 dark:text-slate-400"}`}
                />
                <span
                  className={`text-[10px] font-medium leading-tight truncate w-full text-center tracking-tight ${isActive ? "font-bold" : "text-slate-500 dark:text-slate-400"}`}
                >
                  {tab.name}
                </span>
              </Link>
            );
          })}
        </div>
      </nav>

      {/* More Options Bottom Sheet */}
      <MobileMoreSheet

        isOpen={isMoreOpen}
        onClose={() => setIsMoreOpen(false)}
        instituteCode={instituteCode}
        primaryColor={primaryColor}
        userRole={userRole}
        userName={userName}
        avatarUrl={avatarUrl}
      />
    </>
  );
}

apps/web/src/components/layout/MobileMor.content:
"use client";
import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
  X,
  BookOpen,
  CheckSquare,
  Trophy,
  Award,
  BarChart2,
  Archive,
  PlusSquare,
  ShieldCheck,
  Users,
  FileText,
  Library,
  Flame,
  User,
  Settings,
  LogOut,
  Sparkles,
  type LucideIcon,
} from "lucide-react";
import UserAvatar from "@/components/common/UserAvatar";
import { triggerNativeHaptic, logoutFromNative } from "@/lib/mobile-bridge";

interface MobileMoreSheetProps {
  isOpen: boolean;
  onClose: () => void;
  instituteCode: string;
  primaryColor: string;
  userRole: string;
  userName?: string;
  avatarUrl?: string | null;
}

interface NavItem {
  label: string;
  href: string;
  icon: LucideIcon;
  description?: string;
}

export default function MobileMoreSheet({
  isOpen,
  onClose,
  instituteCode,
  primaryColor,
  userRole,
  userName = "User",
  avatarUrl = null,
}: MobileMoreSheetProps) {
  const pathname = usePathname();
  const router = useRouter();
  const sheetRef = useRef<HTMLDivElement>(null);
  const [loggingOut, setLoggingOut] = useState(false);
  const role = userRole.toUpperCase();
  const isStudent = role === "STUDENT";
  const isProfessor = role === "PROFESSOR" || role === "TEACHER";

  // Lock body scroll when sheet is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  // Handle escape key
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    }
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  const studentItems: NavItem[] = [
    { label: "Flashcards", href: `/${instituteCode}/flashcards`, icon: Flame, description: "Daily review decks" },
    { label: "Materials", href: `/${instituteCode}/learning-materials`, icon: BookOpen, description: "Academic library" },
    { label: "Tasks", href: `/${instituteCode}/tasks`, icon: CheckSquare, description: "Personal planner" },
    { label: "Leaderboards", href: `/${instituteCode}/leaderboards`, icon: Trophy, description: "Institute standings" },
    { label: "Achievements", href: `/${instituteCode}/achievements`, icon: Award, description: "Badges and EXP" },
  ];

  const teacherItems: NavItem[] = [
    { label: "Analytics", href: `/${instituteCode}/analytics`, icon: BarChart2, description: "Student telemetry" },
    { label: "Leaderboard", href: `/${instituteCode}/manage-leaderboard`, icon: Trophy, description: "Manage rankings" },
    { label: "Create Tasks", href: `/${instituteCode}/create-tasks`, icon: PlusSquare, description: "Assign activities" },
    { label: "Archived", href: `/${instituteCode}/courses/archived`, icon: Archive, description: "Previous courses" },
  ];

  const adminItems: NavItem[] = [
    { label: "Courses", href: `/${instituteCode}/admin/courses`, icon: Library, description: "All classes" },
    { label: "Accounts", href: `/${instituteCode}/accounts`, icon: Users, description: "Users & students" },
    { label: "Permissions", href: `/${instituteCode}/accounts/permissions`, icon: ShieldCheck, description: "Role matrix" },
    { label: "Audit Logs", href: `/${instituteCode}/logs`, icon: FileText, description: "System events" },
  ];

  const handleLogout = async () => {
    triggerNativeHaptic("medium");
    setLoggingOut(true);
    try {
      logoutFromNative();
      await fetch("/api/auth/logout", { method: "POST" });
    } catch {
      // ignore
    }
    onClose();
    router.push(`/login?institute=${instituteCode}&force=true`);
  };

  const items = isStudent ? studentItems : isProfessor ? teacherItems : adminItems;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] lg:hidden">
      {/* Backdrop scrim */}
      <div
        className="fixed inset-0 bg-black/60 backdrop-blur-sm transition-opacity duration-300 touch-manipulation"
        onClick={onClose}
        onTouchEnd={(e) => {
          if (e.target === e.currentTarget) {
            e.preventDefault();
            onClose();
          }
        }}
        aria-hidden="true"
      />

      {/* Bottom Sheet Container */}
      <div
        ref={sheetRef}
        role="dialog"
        aria-modal="true"
        aria-label="More navigation options"
        className="fixed inset-x-0 bottom-0 z-10 max-h-[85vh] flex flex-col rounded-t-[28px] border-t border-slate-200/80 dark:border-white/10 bg-white dark:bg-[#141721] shadow-2xl overflow-hidden transition-transform duration-300 ease-out"
      >
        {/* Handle bar + Header */}
        <div className="px-5 pt-3 pb-3 border-b border-slate-100 dark:border-white/5 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-1 rounded-full bg-slate-300 dark:bg-white/20 mx-auto absolute top-2.5 left-1/2 -translate-x-1/2" />
            <h2 className="text-base font-bold text-slate-900 dark:text-[#F0F2F8] mt-1">
              Explore CdM LMS
            </h2>
            <span
              className="mt-1 px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider text-white shrink-0"
              style={{ backgroundColor: primaryColor }}
            >
              {instituteCode.toUpperCase()}
            </span>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-xl p-2 text-slate-400 hover:text-slate-700 dark:hover:text-[#F0F2F8] hover:bg-slate-100 dark:hover:bg-white/5 transition-colors cursor-pointer min-h-[44px] min-w-[44px] flex items-center justify-center touch-manipulation"
            aria-label="Close menu"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* User Card */}
        <div className="px-4 pt-3 pb-2 shrink-0">
          <div className="p-3 rounded-2xl border border-slate-200/70 dark:border-white/10 bg-slate-50/70 dark:bg-white/[0.03] flex items-center justify-between gap-3">
            <div className="flex items-center gap-3 min-w-0 flex-1">
              <UserAvatar
                name={userName}
                avatarUrl={avatarUrl}
                size="sm"
                color={primaryColor}
                className="h-10 w-10 shrink-0 text-xs"
              />
              <div className="min-w-0 flex-1">
                <p className="text-xs font-bold text-slate-900 dark:text-[#F0F2F8] truncate">
                  {userName}
                </p>
                <p className="text-[10px] font-semibold uppercase tracking-wider text-slate-400 dark:text-[#8B92A5] truncate">
                  {userRole}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-1.5 shrink-0">
              <Link
                href={`/${instituteCode}/profile`}
                onClick={() => {
                  triggerNativeHaptic("light");
                  onClose();
                }}
                className="rounded-xl text-slate-600 dark:text-slate-300 hover:bg-slate-200/60 dark:hover:bg-white/10 transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center active:scale-95"
                title="Profile"
                aria-label="Profile"
              >
                <User className="w-4 h-4" />
              </Link>
              <Link
                href={`/${instituteCode}/settings`}
                onClick={() => {
                  triggerNativeHaptic("light");
                  onClose();
                }}
                className="rounded-xl text-slate-600 dark:text-slate-300 hover:bg-slate-200/60 dark:hover:bg-white/10 transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center active:scale-95"
                title="Settings"
                aria-label="Settings"
              >
                <Settings className="w-4 h-4" />
              </Link>
            </div>
          </div>
        </div>

        {/* Scrollable Navigation Grid */}
        <div className="flex-1 overflow-y-auto px-4 py-2">
          <div className="grid grid-cols-2 gap-2.5">
            {items.map((item) => {
              const Icon = item.icon;
              const isActive = pathname === item.href || pathname.startsWith(item.href + "/");

              return (
                <Link
                  key={item.label}
                  href={item.href}
                  onClick={() => {
                    triggerNativeHaptic("light");
                    onClose();
                  }}
                  className={`flex flex-col p-3 rounded-2xl border transition-all cursor-pointer min-h-[72px] active:scale-[0.98] touch-manipulation ${
                    isActive
                      ? "border-transparent bg-slate-100/90 dark:bg-white/10"
                      : "border-slate-200/70 dark:border-white/5 bg-slate-50/50 dark:bg-[#1A1D27] hover:bg-slate-100/70 dark:hover:bg-white/[0.07]"
                  }`}
                  style={
                    isActive
                      ? {
                          borderColor: primaryColor,
                          color: primaryColor,
                        }
                      : undefined
                  }
                >
                  <div className="flex items-center gap-2.5 mb-1 min-w-0">
                    <div
                      className="p-1.5 rounded-xl shrink-0"
                      style={{
                        backgroundColor: isActive ? `${primaryColor}25` : undefined,
                      }}
                    >
                      <Icon
                        className="w-4 h-4"
                        style={{ color: isActive ? primaryColor : undefined }}
                      />
                    </div>
                    <span className="text-xs font-bold text-slate-900 dark:text-[#F0F2F8] truncate flex-1 min-w-0">
                      {item.label}
                    </span>
                  </div>
                  {item.description && (
                    <span className="text-[10px] text-slate-500 dark:text-[#8B92A5] truncate">
                      {item.description}
                    </span>
                  )}
                </Link>
              );
            })}
          </div>
        </div>

        {/* Bottom Sign Out / Switch Account */}
        <div className="p-4 pt-2 pb-[calc(24px+env(safe-area-inset-bottom,0px))] border-t border-slate-100 dark:border-white/5 shrink-0">
          <button
            type="button"
            disabled={loggingOut}
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2.5 py-3 px-4 rounded-2xl bg-rose-500/10 hover:bg-rose-500/20 text-rose-600 dark:text-rose-400 font-bold text-xs border border-rose-500/20 transition-all cursor-pointer active:scale-[0.98] min-h-[48px] touch-manipulation"
          >
            <LogOut className="w-4 h-4" />
            <span>{loggingOut ? "Signing Out..." : "Sign Out / Switch Account"}</span>
          </button>
        </div>
      </div>
    </div>
  );
}

apps/web/src/components/layout/Notificat.content:
"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { useRouter, usePathname } from "next/navigation";
import {
  Bell,
  Megaphone,
  GraduationCap,
  ClipboardCheck,
  CheckCheck,
  Inbox,
  Clock,
  AlertTriangle,
  Radio,
} from "lucide-react";
import type { InstituteTheme } from "@/lib/theme";

interface NotificationItem {
  id: string;
  type: string;
  title: string;
  message: string;
  link: string;
  isRead: boolean;
  createdAt: string;
}

interface NotificationBellProps {
  theme: InstituteTheme;
}

function timeAgo(date: string): string {
  const now = new Date();
  const then = new Date(date);
  const diffMs = now.getTime() - then.getTime();
  const diffMins = Math.floor(diffMs / 60000);

  if (diffMins < 1) return "Just now";
  if (diffMins < 60) return `${diffMins}m ago`;
  const diffHours = Math.floor(diffMins / 60);
  if (diffHours < 24) return `${diffHours}h ago`;
  const diffDays = Math.floor(diffHours / 24);
  if (diffDays < 7) return `${diffDays}d ago`;
  return then.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function getNotificationIcon(type: string) {
  switch (type) {
    case "ANNOUNCEMENT":
      return <Megaphone className="h-4 w-4 text-blue-500" />;
    case "GRADE":
      return <GraduationCap className="h-4 w-4 text-green-500" />;
    case "CLASSWORK":
      return <ClipboardCheck className="h-4 w-4 text-orange-500" />;
    case "REMINDER":
      return <Clock className="h-4 w-4 text-amber-500" />;
    case "ALERT":
      return <AlertTriangle className="h-4 w-4 text-red-500" />;
    case "BROADCAST":
      return <Radio className="h-4 w-4 text-purple-500" />;
    default:
      return <Bell className="h-4 w-4 text-gray-500" />;
  }
}

export default function NotificationBell({ theme }: NotificationBellProps) {
  const router = useRouter();
  const [isOpen, setIsOpen] = useState(false);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);

  // Fetch notifications from API
  const fetchNotifications = useCallback(async () => {
    try {
      const res = await fetch("/api/notifications?limit=20");
      if (!res.ok) return;
      const data = (await res.json()) as {
        notifications: NotificationItem[];
        unreadCount: number;
      };
      setNotifications(data.notifications);
      setUnreadCount(data.unreadCount);
    } catch (err) {
      console.error("Failed to fetch notifications", err);
    }
  }, []);

  // Initial fetch + polling every 30 seconds
  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 30000);
    return () => clearInterval(interval);
  }, [fetchNotifications]);

  const pathname = usePathname();

  // Close panel whenever route changes
  useEffect(() => {
    setIsOpen(false);
  }, [pathname]);

  // Close on outside click or touch
  useEffect(() => {
    function handleClickOutside(event: MouseEvent | TouchEvent) {
      if (panelRef.current && !panelRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("touchstart", handleClickOutside, { passive: true });
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchstart", handleClickOutside);
    };
  }, [isOpen]);

  // Also fetch when opening the panel
  const handleToggle = () => {
    const willOpen = !isOpen;
    setIsOpen(willOpen);
    if (willOpen) {
      fetchNotifications();
    }
  };

  // Mark all as read
  const handleMarkAllRead = async () => {
    setIsLoading(true);
    try {
      await fetch("/api/notifications", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "markAllRead" }),
      });
      setNotifications((prev) => prev.map((n) => ({ ...n, isRead: true })));
      setUnreadCount(0);
    } catch (err) {
      console.error("Failed to mark all read", err);
    } finally {
      setIsLoading(false);
    }
  };

  // Click a notification: mark read + navigate
  const handleClickNotification = async (notification: NotificationItem) => {
    // Mark as read optimistically
    setNotifications((prev) =>
      prev.map((n) => (n.id === notification.id ? { ...n, isRead: true } : n))
    );
    if (!notification.isRead) {
      setUnreadCount((prev) => Math.max(0, prev - 1));
    }

    // Mark as read on server
    try {
      await fetch("/api/notifications", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "markRead", id: notification.id }),
      });
    } catch {
      // silent
    }

    setIsOpen(false);

    // Navigate if link is provided
    if (notification.link) {
      let targetLink = notification.link;
      if (targetLink.includes("/activities/codelab") && !targetLink.includes("alertId=")) {
        targetLink += (targetLink.includes("?") ? "&" : "?") + `alertId=${notification.id}`;
      }
      router.push(targetLink);
    }
  };

  return (
    <div className="relative" ref={panelRef}>
      {/* Bell button */}
      <button
        id="notification-bell"
        onClick={handleToggle}
        className="relative rounded-lg sm:rounded-xl border border-slate-200 dark:border-[rgba(255,255,255,0.07)] bg-white dark:bg-[#22263A] p-1 sm:p-2 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-white/5 transition-all cursor-pointer shadow-xs active:scale-95 h-8 w-8 sm:h-10 sm:w-10 flex items-center justify-center shrink-0"
        aria-label="Notifications"
        aria-expanded={isOpen}
        aria-haspopup="true"
      >
        <Bell className="h-3.5 w-3.5 sm:h-5 sm:w-5" />
        {unreadCount > 0 && (
          <span
            className="absolute -right-1 -top-1 grid h-3.5 w-3.5 sm:h-5 sm:w-5 place-items-center rounded-full text-[8px] sm:text-[10px] font-bold text-white shadow-xs animate-in"
            style={{ backgroundColor: theme.colors.primary }}
          >
            {unreadCount > 9 ? "9+" : unreadCount}
          </span>
        )}
      </button>

      {/* Dropdown panel */}
      <div
        className={`absolute -right-8 sm:right-0 mt-2 w-[min(340px,calc(100vw-24px))] sm:w-96 rounded-xl bg-white dark:bg-[#1A1D27] shadow-xl border border-slate-200/80 dark:border-white/10 ring-1 ring-black/5 dark:ring-0 transition-all duration-200 origin-top-right z-50 ${
          isOpen
            ? "opacity-100 scale-100 pointer-events-auto"
            : "opacity-0 scale-95 pointer-events-none"
        }`}
        style={{ transformOrigin: "top right" }}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100 dark:border-white/10">
          <h3 className="text-sm font-semibold text-slate-900 dark:text-[#F0F2F8]">Notifications</h3>
          {unreadCount > 0 && (
            <button
              id="notification-mark-all-read"
              onClick={handleMarkAllRead}
              disabled={isLoading}
              className="flex items-center gap-1 text-xs font-medium transition-colors hover:underline disabled:opacity-50"
              style={{ color: theme.colors.primary }}
            >
              <CheckCheck className="h-3.5 w-3.5" />
              Mark all as read
            </button>
          )}
        </div>

        {/* Notification list */}
        <div className="max-h-80 overflow-y-auto">
          {notifications.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-10 text-center px-4">
              <Inbox className="h-8 w-8 text-slate-300 dark:text-slate-600 mb-2" />
              <p className="text-sm text-slate-400 dark:text-[#8B92A5]">No notifications yet</p>
              <p className="text-xs text-slate-400 dark:text-slate-500 mt-1">
                You&#39;ll be notified about announcements, grades, and new classwork
              </p>
            </div>
          ) : (
            notifications.map((n) => (
              <button
                key={n.id}
                id={`notification-${n.id}`}
                onClick={() => handleClickNotification(n)}
                className="w-full flex items-start gap-3 px-4 py-3 text-left transition-colors hover:bg-slate-50 dark:hover:bg-white/5 border-b border-slate-100 dark:border-white/5 last:border-b-0"
                style={{
                  backgroundColor: n.isRead ? "transparent" : `${theme.colors.primary}06`,
                }}
              >
                {/* Type icon */}
                <div className="mt-1 shrink-0">{getNotificationIcon(n.type)}</div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <p
                    className={`text-xs font-bold ${
                      n.isRead ? "text-slate-600 dark:text-[#8B92A5]" : "text-slate-900 dark:text-[#F0F2F8]"
                    }`}
                  >
                    {n.title || n.type}
                  </p>
                  <p
                    className={`text-xs mt-0.5 line-clamp-2 leading-relaxed ${
                      n.isRead ? "text-slate-500 dark:text-[#8B92A5]" : "text-slate-800 dark:text-[#D1D5DB] font-medium"
                    }`}
                  >
                    {n.message}
                  </p>
                  <p className="text-[10px] text-slate-400 dark:text-slate-500 mt-1 font-mono">{timeAgo(n.createdAt)}</p>
                </div>

                {/* Unread dot */}
                {!n.isRead && (
                  <div
                    className="h-2 w-2 rounded-full mt-2 shrink-0"
                    style={{ backgroundColor: theme.colors.primary }}
                  />
                )}
              </button>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

apps/web/src/components/layout/Sidebar.t.content:
"use client";

import { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard,
  BookOpen,
  ClipboardCheck,
  Megaphone,
  ListTodo,
  Trophy,
  PanelLeftClose,
  PanelLeftOpen,
  GraduationCap,
  BarChart2,
  PlusSquare,
  Users,
  FileText,
  HardDrive,
  ShieldCheck,
  Library,
  Archive,
  FlaskConical,
  Code2,
  Terminal,
  ChevronDown,
  ChevronRight,
  PenTool,
  Settings,
  HelpCircle,
  MessageSquareQuote,
  X,
  type LucideIcon,
} from "lucide-react";
import FlashcardIcon from "@/components/icons/FlashcardIcon";
import type { InstituteTheme } from "@/lib/theme";


import type { ComponentType } from "react";

interface NavLink {
  label: string;
  href: string;
  icon: ComponentType<{ className?: string }>;
}

export interface EnrolledCourseSummary {
  id: string;
  title: string;
  code: string;
}

interface SidebarProps {
  instituteCode: string;
  theme: InstituteTheme;
  userRole: string;
  isCollapsed?: boolean;
  onToggleCollapse?: () => void;
  isMobileDrawer?: boolean;
  onCloseMobileDrawer?: () => void;
  /** When true, renders the "Interactive Labs" nav entry. Must be completely absent from DOM when false. */
  isEligibleForActivities?: boolean;
  /** When true, renders the "Knowledge Exchange" nav entry. Must be completely absent from DOM when false. */
  isEligibleForKnowledgeExchange?: boolean;
  /** Enrolled courses for the student to render under the "My Courses" accordion. */
  enrolledCourses?: EnrolledCourseSummary[];
}

/** Sidebar link ID for "My Courses" — used to detect the accordion item. */
const MY_COURSES_KEY = "my-courses";

const getStudentLinks = (code: string): (NavLink & { key?: string })[] => [
  { label: "Dashboard", href: `/${code}/students`, icon: LayoutDashboard },
  { label: "My Courses", href: `/${code}/courses`, icon: BookOpen, key: MY_COURSES_KEY },
  { label: "Learning Materials", href: `/${code}/learning-materials`, icon: BookOpen },
  { label: "Announcements", href: `/${code}/announcements`, icon: Megaphone },
  { label: "Grades", href: `/${code}/grades`, icon: GraduationCap },
  { label: "Tasks", href: `/${code}/tasks`, icon: ListTodo },
  { label: "Flashcards", href: `/${code}/flashcards`, icon: FlashcardIcon },
  { label: "Leaderboards", href: `/${code}/leaderboards`, icon: Trophy },
];

const getProfessorLinks = (code: string): (NavLink & { key?: string })[] => [
  { label: "Dashboard", href: `/${code}/teachers`, icon: LayoutDashboard },
  { label: "My Classes", href: `/${code}/courses`, icon: BookOpen, key: MY_COURSES_KEY },
  { label: "Archived Classes", href: `/${code}/courses/archived`, icon: Archive },

  { label: "Student Analytics", href: `/${code}/analytics`, icon: BarChart2 },
  { label: "Manage Leaderboard", href: `/${code}/manage-leaderboard`, icon: Trophy },
];

const getAdminLinks = (code: string): NavLink[] => [
  { label: "Dashboard", href: `/${code}/admin`, icon: LayoutDashboard },
  { label: "Course Management", href: `/${code}/admin/courses`, icon: Library },
  { label: "Account Management", href: `/${code}/accounts`, icon: Users },
  { label: "Permissions", href: `/${code}/accounts/permissions`, icon: ShieldCheck },
  { label: "Audit Logs", href: `/${code}/logs`, icon: FileText },
  { label: "Backup & Recovery", href: `/${code}/backup`, icon: HardDrive },
  { label: "Security Tools", href: `/${code}/security`, icon: ShieldCheck },
  { label: "Settings", href: `/${code}/settings`, icon: Settings },
  { label: "Help", href: `/${code}/help`, icon: HelpCircle },
];

function getLinks(instituteCode: string, role: string): (NavLink & { key?: string })[] {
  const r = role.toUpperCase();
  if (r === "PROFESSOR" || r === "TEACHER") return getProfessorLinks(instituteCode);
  if (r === "ADMIN") return getAdminLinks(instituteCode);
  return getStudentLinks(instituteCode);
}

export default function Sidebar({
  instituteCode,
  theme,
  userRole,
  isCollapsed,
  onToggleCollapse,
  isMobileDrawer = false,
  onCloseMobileDrawer,
  isEligibleForActivities,
  isEligibleForKnowledgeExchange,
  enrolledCourses,
}: SidebarProps) {
  const pathname = usePathname();
  const [isMyCoursesOpen, setIsMyCoursesOpen] = useState(false);

  const isStudent = userRole.toUpperCase() === "STUDENT";
  const isProfessor = userRole.toUpperCase() === "PROFESSOR" || userRole.toUpperCase() === "TEACHER";

  // Build link list identically on both server and client (avoids hydration mismatch)
  let links = getLinks(instituteCode, userRole);

  if (isEligibleForActivities) {
    if (isProfessor) {
      links = [
        ...links,
        { label: "CodeLab", href: `/${instituteCode}/activities/codelab`, icon: Code2 },
        { label: "CodeLab Analytics", href: `/${instituteCode}/activities/codelab/instructor`, icon: Terminal },
      ];
    } else if (isStudent) {
      links = [
        ...links,
        { label: "CodeLab", href: `/${instituteCode}/activities/codelab`, icon: Code2 },
      ];
    }
  }

  if (isEligibleForKnowledgeExchange) {
    links = [
      ...links,
      {
        label: "Knowledge Exchange",
        href: `/${instituteCode}/knowledge-exchange`,
        icon: MessageSquareQuote,
      },
    ];
  }


  // Find the active link by getting the longest href that matches the current pathname
  const activeLink = [...links]
    .sort((a, b) => b.href.length - a.href.length)
    .find(
      (link) => pathname === link.href || pathname.startsWith(link.href + "/")
    );

  const handleMyCoursesToggle = () => {
    setIsMyCoursesOpen((prev) => !prev);
  };

  const handleMyCoursesKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      handleMyCoursesToggle();
    }
  };

  const handleLinkClick = () => {
    if (isMobileDrawer && onCloseMobileDrawer) {
      onCloseMobileDrawer();
    }
  };

  return (
    <aside
      className={`${
        isMobileDrawer
          ? "flex h-full w-full shrink-0 border-r flex-col overflow-y-auto bg-white dark:bg-[#12151E] border-slate-200/80 dark:border-white/5 shadow-2xl"
          : `hidden h-screen border-r flex-col lg:fixed lg:top-0 lg:bottom-0 lg:left-0 lg:z-30 lg:flex transition-all duration-300 ease-in-out overflow-hidden bg-white dark:bg-[#12151E] border-slate-200/80 dark:border-white/5 shadow-xs ${
              isCollapsed ? "w-[72px]" : "w-72"
            }`
      }`}
    >
      {/* Header with logo + collapse toggle */}
      <div className="flex items-center h-16 shrink-0 border-b border-slate-200/80 dark:border-white/5 bg-transparent px-4 gap-2">
        <div
          className={`flex items-center gap-2 overflow-hidden transition-all duration-300 flex-1 min-w-0 ${
            !isMobileDrawer && isCollapsed ? "opacity-0 w-0 pointer-events-none" : "opacity-100"
          }`}
        >
          <Link
            href={`/${instituteCode}`}
            onClick={handleLinkClick}
            className="flex items-center gap-2 group"
          >
            <span
              className="text-lg font-bold text-slate-900 dark:text-[#F0F2F8] tracking-tight whitespace-nowrap transition-colors"
            >
              CdM LMS
            </span>
            <span
              className="h-2 w-2 rounded-full shrink-0 animate-pulse"
              style={{ backgroundColor: theme.colors.primary }}
            />
          </Link>
        </div>

        {isMobileDrawer ? (
          <button
            type="button"
            onClick={onCloseMobileDrawer}
            className="shrink-0 flex items-center justify-center h-8 w-8 rounded-xl text-slate-500 hover:text-slate-900 hover:bg-slate-100 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8] transition-colors cursor-pointer"
            aria-label="Close sidebar"
          >
            <X className="h-5 w-5" />
          </button>
        ) : onToggleCollapse ? (
          <button
            type="button"
            onClick={onToggleCollapse}
            className="shrink-0 flex items-center justify-center h-8 w-8 rounded-xl text-slate-500 hover:text-slate-900 hover:bg-slate-100 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8] transition-colors cursor-pointer"
            aria-label={isCollapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            {isCollapsed ? (
              <PanelLeftOpen className="h-5 w-5" />
            ) : (
              <PanelLeftClose className="h-5 w-5" />
            )}
          </button>
        ) : null}
      </div>

      {/* Scrollable Nav */}
      <nav className="flex-1 overflow-y-auto p-3 flex flex-col gap-1">
        {links.map((item) => {
          const Icon = item.icon;
          const active = activeLink?.href === item.href;
          const itemKey = "key" in item ? item.key : undefined;

          // Render "My Courses" as an accordion for students and professors
          if ((isStudent || isProfessor) && itemKey === MY_COURSES_KEY) {
            const isSubActive =
              (pathname === `/${instituteCode}/courses` ||
                pathname.startsWith(`/${instituteCode}/courses/`)) &&
              !pathname.startsWith(`/${instituteCode}/courses/archived`);

            return (
              <div key={item.href} id="sidebar-my-courses-accordion">
                {/* Accordion header */}
                <div
                  role="button"
                  tabIndex={0}
                  id="sidebar-my-courses-toggle"
                  aria-expanded={isMyCoursesOpen}
                  onClick={handleMyCoursesToggle}
                  onKeyDown={handleMyCoursesKeyDown}
                  className={`group flex items-center gap-2 px-3 py-2.5 text-sm font-medium transition-all cursor-pointer select-none ${
                    isSubActive && !isMyCoursesOpen
                      ? "border-l-[3px] font-semibold rounded-r-xl rounded-l-none"
                      : "border-l-[3px] border-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-100/80 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8] rounded-xl"
                  }`}
                  style={
                    isSubActive && !isMyCoursesOpen
                      ? {
                          borderColor: theme.colors.primary,
                          backgroundColor: `${theme.colors.primary}1A`,
                          color: theme.colors.primary,
                        }
                      : undefined
                  }
                >
                  <Icon className="h-5 w-5 shrink-0 group-hover:scale-105 transition-transform duration-150" />
                  <span
                    className={`overflow-hidden whitespace-nowrap transition-all duration-300 flex-1 min-w-0 ${
                      isCollapsed ? "w-0 opacity-0" : "opacity-100"
                    }`}
                  >
                    {item.label}
                  </span>
                  {!isCollapsed && (
                    <span className="shrink-0">
                      <ChevronDown
                        className={`h-4 w-4 transition-transform duration-200 text-slate-400 dark:text-[#555C72] ${
                          isMyCoursesOpen ? "rotate-0" : "-rotate-90"
                        }`}
                      />
                    </span>
                  )}
                </div>

                {/* Accordion content */}
                {!isCollapsed && (
                  <div
                    className="overflow-hidden transition-all duration-300 ease-in-out"
                    style={{
                      maxHeight: isMyCoursesOpen ? `${((enrolledCourses?.length ?? 0) + 2) * 44}px` : "0px",
                      opacity: isMyCoursesOpen ? 1 : 0,
                    }}
                  >
                    <div className="flex flex-col gap-0.5 mt-1">
                      {/* To-do sub-link (Students only) */}
                      {isStudent && (
                        <Link
                          id="sidebar-my-courses-todo"
                          href={`/${instituteCode}/assignments`}
                          onClick={handleLinkClick}
                          className={`flex items-center gap-2 rounded-xl pl-8 pr-3 py-2 text-xs font-medium transition-colors ${
                            pathname === `/${instituteCode}/assignments` ||
                            pathname.startsWith(`/${instituteCode}/assignments/`)
                              ? "font-semibold"
                              : "text-slate-600 hover:text-slate-900 hover:bg-slate-100/80 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8]"
                          }`}
                          style={
                            pathname === `/${instituteCode}/assignments` ||
                            pathname.startsWith(`/${instituteCode}/assignments/`)
                              ? {
                                  backgroundColor: `${theme.colors.primary}1A`,
                                  color: theme.colors.primary,
                                }
                              : undefined
                          }
                        >
                          <ClipboardCheck className="h-4 w-4 shrink-0" />
                          <span className="truncate">To-do</span>
                        </Link>
                      )}

                      {/* Enrolled course sub-links */}
                      {enrolledCourses?.map((course) => {
                        const courseHref = `/${instituteCode}/courses/${course.id}`;
                        const isCourseActive =
                          pathname === courseHref || pathname.startsWith(courseHref + "/");

                        return (
                          <Link
                            key={course.id}
                            id={`sidebar-course-${course.id}`}
                            href={courseHref}
                            onClick={handleLinkClick}
                            className={`flex items-center gap-2 rounded-xl pl-8 pr-3 py-2 text-xs font-medium transition-colors ${
                              isCourseActive
                                ? "font-semibold"
                                : "text-slate-600 hover:text-slate-900 hover:bg-slate-100/80 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8]"
                            }`}
                            style={
                              isCourseActive
                                ? {
                                    backgroundColor: `${theme.colors.primary}1A`,
                                    color: theme.colors.primary,
                                  }
                                : undefined
                            }
                          >
                            <BookOpen className="h-4 w-4 shrink-0" />
                            <span className="truncate">{course.code}</span>
                          </Link>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            );
          }

          // Regular flat nav link
          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={handleLinkClick}
              title={isCollapsed ? item.label : undefined}
              className={`group flex items-center gap-2 px-3 py-2.5 text-sm font-medium transition-all ${
                active
                  ? "border-l-[3px] font-semibold rounded-r-xl rounded-l-none"
                  : "border-l-[3px] border-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-100/80 dark:text-[#8B92A5] dark:hover:bg-white/[0.05] dark:hover:text-[#F0F2F8] rounded-xl"
              }`}
              style={
                active
                  ? {
                      borderColor: theme.colors.primary,
                      backgroundColor: `${theme.colors.primary}1A`,
                      color: theme.colors.primary,
                    }
                  : undefined
              }
            >
              <Icon className="h-5 w-5 shrink-0 group-hover:scale-105 transition-transform duration-150" />
              <span
                className={`overflow-hidden whitespace-nowrap transition-all duration-300 ${
                  isCollapsed ? "w-0 opacity-0" : "opacity-100"
                }`}
              >
                {item.label}
              </span>
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}

apps/web/src/components/layout/Topbar.ts.content:
"use client";

import { useState, useRef, useEffect } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { Bell, Menu, Search, Settings, User, Shield, HelpCircle, LogOut, Sun, Moon, ChevronDown, Check, Building2 } from "lucide-react";
import type { InstituteTheme } from "@/lib/theme";
import UserAvatar from "@/components/common/UserAvatar";
import NotificationBell from "@/components/layout/NotificationBell";
import LevelBadge from "@/components/common/LevelBadge";
import SearchModal from "@/components/layout/SearchModal";
import { useTheme } from "@/lib/theme-context";
import { triggerNativeHaptic, logoutFromNative } from "@/lib/mobile-bridge";

const ALL_INSTITUTES = [
  { code: "ics", name: "Institute of Computer Studies", short: "ICS", color: "#E06A26" },
  { code: "ibe", name: "Institute of Business and Education", short: "IBE", color: "#EAB308" },
  { code: "ite", name: "Institute of Technology and Engineering", short: "ITE", color: "#0284C7" },
];

type TopbarProps = {
  theme: InstituteTheme;
  instituteName: string;
  userName: string;
  userRole: string;
  instituteCode: string;
  studentNumber?: string | null;
  avatarUrl?: string | null;
  exp?: number;
  onOpenMobileMenu?: () => void;
};

export default function Topbar({
  theme,
  instituteName,
  userName,
  userRole,
  instituteCode,
  studentNumber,
  avatarUrl,
  exp = 0,
  onOpenMobileMenu,
}: TopbarProps) {
  const pathname = usePathname();
  const router = useRouter();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isInstituteSwitcherOpen, setIsInstituteSwitcherOpen] = useState(false);
  const [searchModalOpen, setSearchModalOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const instituteSwitcherRef = useRef<HTMLDivElement>(null);
  const { themeMode, toggleTheme } = useTheme();

  const isAdmin = userRole.toUpperCase() === "ADMIN";

  function handleSwitchInstitute(targetCode: string) {
    setIsInstituteSwitcherOpen(false);
    setIsDropdownOpen(false);
    if (targetCode.toLowerCase() === instituteCode.toLowerCase()) return;
    const segments = pathname.split("/").filter(Boolean);
    if (segments.length > 0 && segments[0].toLowerCase() === instituteCode.toLowerCase()) {
      segments[0] = targetCode.toLowerCase();
      router.push("/" + segments.join("/"));
    } else {
      router.push(`/${targetCode.toLowerCase()}/admin`);
    }
  }

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setSearchModalOpen((prev) => !prev);
      }
    }
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  // Close dropdowns whenever route changes
  useEffect(() => {
    setIsDropdownOpen(false);
    setIsInstituteSwitcherOpen(false);
  }, [pathname]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent | TouchEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
      if (instituteSwitcherRef.current && !instituteSwitcherRef.current.contains(event.target as Node)) {
        setIsInstituteSwitcherOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("touchstart", handleClickOutside, { passive: true });
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchstart", handleClickOutside);
    };
  }, []);

  async function handleLogout() {
    try {
      triggerNativeHaptic("light");
      logoutFromNative();
      await fetch("/api/auth/logout", { method: "POST" });
      window.location.href = `/login?institute=${instituteCode}&force=true`;
    } catch (error) {
      console.error("Logout failed", error);
      window.location.href = `/login?institute=${instituteCode}&force=true`;
    }
  }

  let dynamicTitle = "Dashboard";
  const segment = pathname.split("/").pop();

  const titleMap: Record<string, string> = {
    // Student
    students: "Student Dashboard",
    courses: "My Courses",
    announcements: "Announcements",
    assignments: "To-do",
    tasks: "Tasks",
    leaderboards: "Leaderboards",
    // Professor
    teachers: "Teacher Dashboard",
    classes: "My Classes",
    analytics: "Student Analytics",
    "create-tasks": "Create Tasks",
    "manage-leaderboard": "Manage Leaderboard",
    // Admin
    admin: "Admin Dashboard",
    accounts: "Account Management",
    permissions: "Permission Matrix",
    logs: "Audit Logs",
    backup: "Backup & Recovery",
    security: "Security Tools",
    // Course Management
    "course-management": "Course Management",
    stream: "Stream",
    classwork: "Classwork",
    people: "People",
    // Activities
    codelab: "CodeLab Problem Bank",
    instructor: "CodeLab Analytics",
    // Shared
    settings: "Settings",
    profile: "Profile",
    privacy: "Privacy Settings",
    "learning-materials": "Learning Materials",
    help: "Help & Support",
  };

  if (segment && titleMap[segment]) {
    dynamicTitle = titleMap[segment];
  }
  return (
    <header className="sticky top-0 z-50 border-b border-slate-200/80 dark:border-[rgba(255,255,255,0.07)] bg-white dark:bg-[#1A1D27] sm:bg-white/95 sm:dark:bg-[#1A1D27]/95 sm:backdrop-blur-md transition-colors duration-200 min-h-[48px] sm:min-h-[56px] flex flex-col justify-center">
      <div className="flex items-center justify-between gap-1.5 sm:gap-3 px-2.5 sm:px-4 lg:px-8 py-1.5 sm:py-3">
        {/* Left Side: Menu + Institute Badge + Dynamic Title */}
        <div className="flex flex-1 min-w-0 items-center gap-1.5 sm:gap-2.5">
          <button
            type="button"
            onClick={onOpenMobileMenu}
            className="rounded-lg sm:rounded-xl border border-slate-200 dark:border-[rgba(255,255,255,0.07)] p-1 sm:p-2 text-slate-700 dark:text-slate-300 lg:hidden hover:bg-slate-50 dark:hover:bg-white/5 transition-colors cursor-pointer h-8 w-8 sm:h-10 sm:w-10 flex items-center justify-center shrink-0 touch-manipulation active:scale-95"
            aria-label="Open menu"
          >
            <Menu className="h-4 w-4 sm:h-5 sm:w-5" />
          </button>

          {/* Mobile Institute Badge & Title */}
          <div className="md:hidden flex items-center gap-1.5 min-w-0 flex-1">
            {isAdmin ? (
              <div className="relative" ref={instituteSwitcherRef}>
                <button
                  type="button"
                  onClick={() => setIsInstituteSwitcherOpen((prev) => !prev)}
                  className="px-1.5 py-0.5 rounded text-[9px] sm:text-[10px] font-black uppercase tracking-wider text-white shrink-0 shadow-xs flex items-center gap-1 active:scale-95 transition-transform"
                  style={{ backgroundColor: theme.colors.primary }}
                  aria-label="Switch institute campus"
                >
                  {instituteCode.toUpperCase()}
                  <ChevronDown className={`h-2.5 w-2.5 transition-transform duration-200 ${isInstituteSwitcherOpen ? "rotate-180" : ""}`} />
                </button>

                {isInstituteSwitcherOpen && (
                  <div className="absolute left-0 top-full mt-2 w-56 rounded-2xl bg-white dark:bg-[#22263A] border border-slate-200 dark:border-white/10 p-2 shadow-2xl z-50 animate-in fade-in zoom-in-95 duration-150">
                    <div className="px-2.5 py-1 text-[9px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500">
                      Switch Campus
                    </div>
                    <div className="space-y-1 mt-1">
                      {ALL_INSTITUTES.map((inst) => {
                        const isCurrent = inst.code.toLowerCase() === instituteCode.toLowerCase();
                        return (
                          <button
                            key={inst.code}
                            type="button"
                            onClick={() => handleSwitchInstitute(inst.code)}
                            className={`flex items-center justify-between w-full px-2.5 py-2 rounded-xl text-xs font-semibold transition-all cursor-pointer ${
                              isCurrent
                                ? "bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-white"
                                : "text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-white/5"
                            }`}
                          >
                            <div className="flex items-center gap-2 min-w-0">
                              <span
                                className="px-1.5 py-0.5 rounded text-[9px] font-black uppercase text-white shrink-0"
                                style={{ backgroundColor: inst.color }}
                              >
                                {inst.short}
                              </span>
                              <span className="truncate text-left text-xs">{inst.name}</span>
                            </div>
                            {isCurrent && <Check className="h-3.5 w-3.5 text-emerald-500 shrink-0 ml-1.5" />}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <span
                className="px-1.5 py-0.5 rounded text-[9px] sm:text-[10px] font-black uppercase tracking-wider text-white shrink-0 shadow-xs flex items-center"
                style={{ backgroundColor: theme.colors.primary }}
              >
                {instituteCode.toUpperCase()}
              </span>
            )}
            <h1 className="text-xs sm:text-sm font-bold tracking-tight text-slate-900 dark:text-[#F0F2F8] truncate min-w-0 flex-1" title={dynamicTitle}>
              {dynamicTitle}
            </h1>
          </div>

          {/* Desktop & Tablet Title & Institute Badge / Switcher */}
          <div className="hidden md:flex items-center gap-3 min-w-0">
            {isAdmin ? (
              <div className="relative" ref={instituteSwitcherRef}>
                <button
                  type="button"
                  onClick={() => setIsInstituteSwitcherOpen((prev) => !prev)}
                  className="flex items-center gap-2 px-2.5 py-1.5 rounded-xl border border-slate-200 dark:border-white/10 bg-slate-50/80 dark:bg-white/[0.03] hover:bg-slate-100 dark:hover:bg-white/[0.06] transition-all shadow-xs cursor-pointer text-left group"
                  title="Click to switch institute campus"
                  aria-expanded={isInstituteSwitcherOpen}
                >
                  <span
                    className="px-1.5 py-0.5 rounded text-[10px] font-black uppercase tracking-wider text-white shrink-0 shadow-xs"
                    style={{ backgroundColor: theme.colors.primary }}
                  >
                    {instituteCode.toUpperCase()}
                  </span>
                  <div className="flex flex-col min-w-0">
                    <span className="text-[9px] font-semibold uppercase tracking-wider text-slate-400 dark:text-slate-500 leading-none mb-0.5 flex items-center gap-1">
                      Campus Switcher
                    </span>
                    <span className="text-xs font-bold text-slate-800 dark:text-[#F0F2F8] truncate max-w-[140px] lg:max-w-[200px] leading-tight">
                      {instituteName}
                    </span>
                  </div>
                  <ChevronDown className={`h-3.5 w-3.5 text-slate-400 group-hover:text-slate-600 dark:group-hover:text-slate-200 transition-transform duration-200 shrink-0 ${isInstituteSwitcherOpen ? "rotate-180" : ""}`} />
                </button>

                {/* Institute Switcher Dropdown */}
                {isInstituteSwitcherOpen && (
                  <div className="absolute left-0 mt-2 w-72 rounded-2xl bg-white dark:bg-[#22263A] border border-slate-200 dark:border-white/10 p-2.5 shadow-2xl z-50 animate-in fade-in zoom-in-95 duration-150">
                    <div className="px-2 py-1 text-[10px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500 flex items-center gap-1.5">
                      <Building2 className="h-3 w-3" />
                      Switch Campus Portal
                    </div>
                    <div className="space-y-1 mt-1.5">
                      {ALL_INSTITUTES.map((inst) => {
                        const isCurrent = inst.code.toLowerCase() === instituteCode.toLowerCase();
                        return (
                          <button
                            key={inst.code}
                            type="button"
                            onClick={() => handleSwitchInstitute(inst.code)}
                            className={`flex items-center justify-between w-full px-2.5 py-2 rounded-xl text-xs font-semibold transition-all cursor-pointer ${
                              isCurrent
                                ? "bg-slate-100 dark:bg-white/10 text-slate-900 dark:text-white"
                                : "text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-white/5"
                            }`}
                          >
                            <div className="flex items-center gap-2.5 min-w-0">
                              <span
                                className="px-1.5 py-0.5 rounded text-[10px] font-black uppercase text-white shrink-0"
                                style={{ backgroundColor: inst.color }}
                              >
                                {inst.short}
                              </span>
                              <span className="truncate text-left text-xs">{inst.name}</span>
                            </div>
                            {isCurrent && <Check className="h-4 w-4 text-emerald-500 shrink-0 ml-1.5" />}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center gap-2 px-2.5 py-1.5 rounded-xl border border-slate-200 dark:border-white/10 bg-slate-50/80 dark:bg-white/[0.03] shadow-xs">
                <span
                  className="px-1.5 py-0.5 rounded text-[10px] font-black uppercase tracking-wider text-white shrink-0 shadow-xs"
                  style={{ backgroundColor: theme.colors.primary }}
                >
                  {instituteCode.toUpperCase()}
                </span>
                <div className="flex flex-col min-w-0">
                  <span className="text-[10px] font-semibold uppercase tracking-wider text-slate-400 dark:text-slate-500 leading-none mb-0.5">
                    Campus
                  </span>
                  <span className="text-xs font-bold text-slate-800 dark:text-[#F0F2F8] truncate max-w-[140px] lg:max-w-[200px] leading-tight">
                    {instituteName}
                  </span>
                </div>
              </div>
            )}

            <div className="h-6 w-px bg-slate-200 dark:bg-white/10 shrink-0" />

            <h1 className="text-sm lg:text-base xl:text-lg font-bold tracking-tight text-slate-900 dark:text-[#F0F2F8] truncate max-w-[160px] lg:max-w-[240px] xl:max-w-none">
              {dynamicTitle}
            </h1>
          </div>
        </div>

        {/* Right Side Controls */}
        <div className="flex flex-none items-center justify-end gap-1 sm:gap-1.5 lg:gap-2.5 shrink-0">
          {/* Search bar Desktop (Wide only on xl+) */}
          <button
            type="button"
            onClick={() => setSearchModalOpen(true)}
            className="hidden w-full max-w-xs xl:max-w-sm 2xl:max-w-md items-center justify-between gap-2.5 rounded-xl border border-slate-200 dark:border-[#3D4460] bg-slate-100/80 dark:bg-[#1E2132] px-3.5 py-2 xl:flex transition-all text-left cursor-pointer"
            style={{
              borderColor: undefined,
            }}
          >
            <div className="flex items-center gap-2.5 min-w-0">
              <Search className="h-4 w-4 text-slate-400 dark:text-[#8B92A5] shrink-0" />
              <span className="text-sm text-slate-400 dark:text-[#555C72] truncate">
                Search courses, notes, or peers...
              </span>
            </div>
            <kbd className="hidden sm:inline-flex items-center gap-0.5 rounded border border-slate-300 dark:border-white/10 bg-white dark:bg-white/5 px-1.5 py-0.5 text-[10px] font-medium text-slate-500 dark:text-[#8B92A5]">
              ⌘K
            </kbd>
          </button>
          
          {/* Mobile & Tablet Compact Search Button - only on sm+ to keep mobile header clean */}
          <button
            type="button"
            onClick={() => setSearchModalOpen(true)}
            className="hidden sm:flex xl:hidden relative rounded-lg sm:rounded-xl border border-slate-200 dark:border-[rgba(255,255,255,0.07)] bg-white dark:bg-[#22263A] p-1 sm:p-2 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-white/5 transition-all cursor-pointer shadow-xs active:scale-95 h-8 w-8 sm:h-10 sm:w-10 items-center justify-center shrink-0"
            aria-label="Search"
          >
