                <div className="flex items-center gap-1.5 justify-end">
                  <p className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 dark:text-[#8B92A5] shrink-0">
                    {userRole}
                  </p>
                  {userRole === "STUDENT" && studentNumber && (
                    <>
                      <span className="h-1 w-1 rounded-full bg-slate-300 dark:bg-slate-700 shrink-0" />
                      <p className="text-[11px] font-mono text-slate-500 dark:text-[#8B92A5] truncate">{studentNumber}</p>
                    </>
                  )}
                </div>
              </div>
              <UserAvatar
                name={userName}
                avatarUrl={avatarUrl}
                size="sm"
                color={theme.colors.primary}
                className="h-7 w-7 sm:h-8 sm:w-8 text-xs"
              />
            </button>

            <div
              className={`absolute right-0 mt-2 w-48 rounded-2xl bg-white dark:bg-[#22263A] border border-slate-200 dark:border-[rgba(255,255,255,0.1)] py-1.5 shadow-xl transition-all duration-200 origin-top-right ${
                isDropdownOpen
                  ? "opacity-100 scale-100 pointer-events-auto"
                  : "opacity-0 scale-95 pointer-events-none"
              }`}
              style={{ transformOrigin: "top right" }}
            >
              <Link
                href={`/${instituteCode}/profile`}
                onClick={() => setIsDropdownOpen(false)}
                className="flex items-center px-4 py-2 text-sm text-slate-700 dark:text-[#F0F2F8] hover:bg-slate-50 dark:hover:bg-white/5 transition-colors font-medium"
              >
                <User className="mr-3 h-4 w-4 text-slate-400 dark:text-[#8B92A5]" aria-hidden="true" />
                Profile
              </Link>
              <Link
                href={`/${instituteCode}/settings`}
                onClick={() => setIsDropdownOpen(false)}
                className="flex items-center px-4 py-2 text-sm text-slate-700 dark:text-[#F0F2F8] hover:bg-slate-50 dark:hover:bg-white/5 transition-colors font-medium"
              >
                <Settings className="mr-3 h-4 w-4 text-slate-400 dark:text-[#8B92A5]" aria-hidden="true" />
                Settings
              </Link>
              <Link
                href={`/${instituteCode}/privacy`}
                onClick={() => setIsDropdownOpen(false)}
                className="flex items-center px-4 py-2 text-sm text-slate-700 dark:text-[#F0F2F8] hover:bg-slate-50 dark:hover:bg-white/5 transition-colors font-medium"
              >
                <Shield className="mr-3 h-4 w-4 text-slate-400 dark:text-[#8B92A5]" aria-hidden="true" />
                Privacy
              </Link>
              <Link
                href={`/${instituteCode}/help`}
                onClick={() => setIsDropdownOpen(false)}
                className="flex items-center px-4 py-2 text-sm text-slate-700 dark:text-[#F0F2F8] hover:bg-slate-50 dark:hover:bg-white/5 transition-colors font-medium"
              >
                <HelpCircle className="mr-3 h-4 w-4 text-slate-400 dark:text-[#8B92A5]" aria-hidden="true" />
                Help
              </Link>

              {isAdmin && (
                <div className="border-t border-slate-200 dark:border-white/10 my-1 py-1">
                  <div className="px-4 py-1 text-[10px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500">
                    Switch Campus
                  </div>
                  {ALL_INSTITUTES.map((inst) => {
                    const isCurrent = inst.code.toLowerCase() === instituteCode.toLowerCase();
                    return (
                      <button
                        key={inst.code}
                        type="button"
                        onClick={() => handleSwitchInstitute(inst.code)}
                        className={`flex items-center justify-between w-full px-4 py-1.5 text-xs font-semibold transition-colors cursor-pointer ${
                          isCurrent
                            ? "text-slate-900 dark:text-white bg-slate-50 dark:bg-white/5 font-bold"
                            : "text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-white/5"
                        }`}
                      >
                        <span className="flex items-center gap-2">
                          <span
                            className="h-2 w-2 rounded-full"
                            style={{ backgroundColor: inst.color }}
                          />
                          {inst.short} Campus
                        </span>
                        {isCurrent && <Check className="h-3.5 w-3.5 text-emerald-500" />}
                      </button>
                    );
                  })}
                </div>
              )}

              <button
                onClick={handleLogout}
                className="flex w-full items-center px-4 py-2 text-sm text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/20 transition-colors font-semibold cursor-pointer border-t border-slate-200/60 dark:border-white/5"
              >
                <LogOut className="mr-3 h-4 w-4 text-rose-500" aria-hidden="true" />
                Logout
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Global Command / Search Palette Modal */}
      <SearchModal
        isOpen={searchModalOpen}
        onClose={() => setSearchModalOpen(false)}
        instituteCode={instituteCode}
        theme={theme}
        userRole={userRole}
      />
    </header>
  );
}

apps/web/src/lib/activity-eligibility.ts.content:
/**
 * Activity Eligibility Guard
 *
 * Single source of truth for determining whether a user can access
 * the Interactive Activities feature suite (3D simulations, CodeLab).
 *
 * RULE: Only users belonging to the Institute of Computer Studies (ICS)
 * are eligible. ICS exclusively houses BSIT and BSCpE programs at CDM.
 *
 * If a Program model is added to the schema in the future, refine the
 * check here — every consumer imports from this module, so the change
 * propagates automatically.
 *
 * Used by:
 *   - Route layout: apps/web/src/app/(dashboard)/[institute]/activities/layout.tsx
 *   - API routes:   apps/web/src/app/api/activities/submit/route.ts
 *   - Sidebar:      apps/web/src/components/layout/Sidebar.tsx (conditional nav entry)
 */

import { db } from "./db";
import { getSession } from "./auth-session";
import { normalizeRole } from "./admin-types";

/** The institute code that gates access to Interactive Activities. */
const ELIGIBLE_INSTITUTE_CODE = "ics";

/**
 * Minimal session shape needed for eligibility checks.
 * Avoids coupling to the full Prisma Session type.
 */
interface EligibilitySession {
  user: {
    id: string;
    role: string;
    instituteId: string;
  };
}

/**
 * Checks if a user session is eligible for Interactive Activities.
 *
 * Eligible when:
 *   - The user's institute code is "ics" (Institute of Computer Studies)
 *   - Students: must be enrolled under ICS
 *   - Instructors: must belong to ICS (they teach ICS courses by definition,
 *     since Course.instituteId matches the instructor's institute)
 *   - Admins at ICS: eligible (can manage activities)
 *
 * @param session - A session object containing at least user.id, user.role, user.instituteId
 * @returns true if the user may access activity features
 */
export async function isEligibleForActivities(
  session: EligibilitySession
): Promise<boolean> {
  // Look up the institute to get its code
  const institute = await db.institute.findUnique({
    where: { id: session.user.instituteId },
    select: { code: true },
  });

  if (!institute) return false;

  return institute.code.toLowerCase() === ELIGIBLE_INSTITUTE_CODE;
}

/**
 * Synchronous eligibility check when institute code is already known.
 * Useful in client components where the institute code comes from the route param.
 *
 * @param instituteCode - The institute code from the URL (e.g. "ics", "ibe")
 * @returns true if this institute code qualifies for activity features
 */
export function isEligibleInstituteCode(instituteCode: string): boolean {
  return instituteCode.toLowerCase() === ELIGIBLE_INSTITUTE_CODE;
}

/**
 * Full eligibility check for API route handlers.
 * Reads the session from the cookie, validates it, and checks eligibility.
 *
 * @returns Object with eligibility result and session, or null if no valid session.
 * @throws Never — returns null on auth failure so callers can choose their own error shape.
 */
export async function checkActivityEligibility(): Promise<{
  eligible: boolean;
  session: NonNullable<Awaited<ReturnType<typeof getSession>>>;
  role: ReturnType<typeof normalizeRole>;
} | null> {
  const session = await getSession();
  if (!session) return null;

  const role = normalizeRole(session.user.role as string);
  const eligible = await isEligibleForActivities({
    user: {
      id: session.user.id,
      role: session.user.role as string,
      instituteId: session.user.instituteId as string,
    },
  });

  return { eligible, session, role };
}

