import { test, expect, APIRequestContext } from '@playwright/test';
import { loadFixture, institutes, prohibitedRoles, auth, overview, detail, assertSeeded, overviewShape, detailShape, errorShape, noSensitive, stateFingerprint, auditBaseline, assertAuditAppendOnly, database, controllerEvidence, auditRead, httpMutations, activityPayload, Role, Institute } from './fixture';

const f = loadFixture();
test.describe.configure({ mode: 'serial' });
test.use({ storageState: { cookies: [], origins: [] } });
test.beforeAll(async () => { await assertSeeded(f); });
async function denial(request: APIRequestContext, url: string, role?: Role, status = role && role !== 'INACTIVE_USER' ? 403 : 401) {
  const response = await request.get(url, role ? { headers: auth(f, role) } : {});
  expect(response.status()).toBe(status); errorShape(f, await response.json());
}

for (const selected of institutes) test(`AC-001 AC-009 AC-010 authentication/authorization: every protected ${selected} endpoint rejects prohibited identities`, async ({ request }) => {
  for (const url of [overview(f, selected), detail(f, selected, f.courses[selected].id)]) {
    await denial(request, url);
    for (const role of prohibitedRoles) await denial(request, url, role);
  }
});

for (const selected of institutes) test(`AC-002 AC-003 AC-004 AC-007 selected ${selected}: exact safe DTO, scope, course and assigned instructor`, async ({ request }) => {
  const before = await stateFingerprint(), audits = await auditBaseline(), start = new Date();
  const list = await request.get(overview(f, selected), { headers: auth(f, 'SUPER_USER') }); expect(list.status()).toBe(200);
  const listed = overviewShape(f, await list.json(), selected), ids = (listed.courses as { id: string }[]).map(c => c.id);
  expect(ids).toContain(f.courses[selected].id); if (selected === 'ics') expect(ids).toContain(f.superAssignedCourse.id);
  for (const other of institutes) if (other !== selected) expect(JSON.stringify(listed)).not.toContain(f.courses[other].id);
  const response = await request.get(detail(f, selected, f.courses[selected].id), { headers: auth(f, 'SUPER_USER') }); expect(response.status()).toBe(200);
  const body = detailShape(f, await response.json(), selected, f.courses[selected]);
  expect((body.schedule as { id: string }[]).map(v => v.id)).toContain(f.courses[selected].scheduleId);
  expect((body.materials as { id: string }[]).map(v => v.id)).toContain(f.courses[selected].materialId);
  expect((body.announcements as { id: string }[]).map(v => v.id)).toContain(f.courses[selected].announcementId);
  await auditRead(f, 'SUPER_USER_ACADEMIC_OVERSIGHT_READ', selected, null, start);
  await auditRead(f, 'SUPER_USER_COURSE_SUPERVISION_READ', selected, f.courses[selected].id, start);
  expect(await stateFingerprint()).toBe(before); await assertAuditAppendOnly(audits);
  controllerEvidence({ actor: 'SUPER_USER', institute: selected, target: f.courses[selected].id, operation: 'oversight-list-and-detail', outcome: 'ALLOWED', status: 200, before, after: before });
});

test('AC-002 AC-005 AC-009 AC-010 IDOR: foreign course IDs, unknown/encoded scopes and fabricated ownership do not expose data', async ({ request }) => {
  for (const selected of institutes) for (const foreign of institutes) if (selected !== foreign) {
    const response = await request.get(detail(f, selected, f.courses[foreign].id), { headers: auth(f, 'SUPER_USER') }); expect(response.status()).toBe(404);
    const body = await response.json(); errorShape(f, body); expect(JSON.stringify(body)).not.toContain(f.courses[foreign].title);
  }
  for (const scope of ['unsupported', 'ics/ibe', 'ics%00']) {
    const response = await request.get(overview(f, scope), { headers: auth(f, 'SUPER_USER') }); expect([400, 403, 404]).toContain(response.status()); noSensitive(f, await response.text());
  }
  for (const role of ['STUDENT', 'OTHER_STUDENT', 'UNASSIGNED_INSTRUCTOR', 'FOREIGN_INSTRUCTOR'] as Role[]) {
    await denial(request, detail(f, 'ics', f.superAssignedCourse.id) + '?ownerId=' + f.accounts[role].id, role);
  }
});

test('AC-002 AC-003 AC-009 AC-010 request-manipulation/program-scope: route scope wins; unsupported program claims do not grant activity access', async ({ request }) => {
  const query = '?institute=ics&institute=ite&instituteId=' + f.courses.ics.instituteId + '&program=BSIT&programId=forged-program&ownerId=' + f.accounts.INSTRUCTOR.id;
  const headers = { ...auth(f, 'SUPER_USER'), 'X-Institute': 'ics', 'X-Program': 'BSIT', 'X-Role': 'ADMIN', 'X-User-Id': f.accounts.ADMIN.id };
  for (const url of [overview(f, 'ibe'), detail(f, 'ibe', f.courses.ibe.id)]) {
    const response = await request.get(url + query, { headers }); expect(response.status()).toBe(200);
    const body = await response.json(); if (url === overview(f, 'ibe')) overviewShape(f, body, 'ibe'); else detailShape(f, body, 'ibe', f.courses.ibe);
    expect(JSON.stringify(body)).not.toContain(f.courses.ics.id);
  }
  // Existing repository has no Program model. Its ICS activity guard represents
  // the BSIT/BSCpE boundary; caller-supplied program claims cannot replace it.
  for (const role of ['SUPER_USER', 'FOREIGN_INSTRUCTOR'] as Role[]) {
    const response = await request.post(f.baseURL + '/api/activities/submit', { headers: { ...auth(f, role), 'X-Program': 'BSIT', 'X-Institute': 'ics' }, data: { ...activityPayload(f, role, 'ics'), program: 'BSIT', programId: 'forged', institute: 'ics' } });
    expect(response.status()).toBe(403); errorShape(f, await response.json());
  }
});

test('AC-001 AC-006 AC-007 AC-010: generic course/admin/student/assessment reads cannot bypass the dedicated supervision contract', async ({ request }) => {
  const paths = ['/api/admin/users', '/api/admin/permissions', '/api/admin/audit-logs', '/api/courses?institute=ics', '/api/workspace/events'];
  for (const c of [...Object.values(f.courses), f.superAssignedCourse]) {
    paths.push(`/api/courses/${c.id}`);
    for (const suffix of ['people', 'grades', 'gradebook', 'submissions', 'enrollments', 'classwork', 'stream']) paths.push(`/api/courses/${c.id}/${suffix}`);
  }
  for (const candidate of paths) await denial(request, f.baseURL + candidate, 'SUPER_USER');
});

for (const selected of institutes) test(`AC-001 AC-006 AC-010 AC-011 ${selected}: semantically typed HTTP mutations are forbidden and preserve all state`, async ({ request }) => {
  const cases = httpMutations(f, selected), categories = new Set(cases.map(c => c.category));
  for (const required of ['schedule-edit', 'grade-work', 'enrollment-edit', 'assessment-submit', 'admin-only']) expect(categories.has(required as never)).toBe(true);
  for (const candidate of cases) {
    const before = await stateFingerprint(), audits = await auditBaseline();
    const response = await request.fetch(f.baseURL + candidate.path, { method: candidate.method, headers: auth(f, 'SUPER_USER'), data: 'body' in candidate ? candidate.body : undefined });
    expect(response.status(), candidate.category + ' ' + candidate.path).toBe(403); errorShape(f, await response.json());
    const after = await stateFingerprint(); expect(after).toBe(before); await assertAuditAppendOnly(audits);
    controllerEvidence({ actor: 'SUPER_USER', institute: selected, target: f.courses[selected].id, operation: candidate.category + ':' + candidate.method + ':' + candidate.path, outcome: 'DENIED', status: response.status(), before, after });
  }
});

test('AC-008 AC-010 AC-011: existing Admin administration and assigned-instructor teaching retain real authorized operations', async ({ request }) => {
  for (const role of ['ADMIN', 'INSTRUCTOR', 'STUDENT'] as Role[]) {
    const response = await request.get(`${f.baseURL}/api/courses/${f.courses.ics.id}`, { headers: auth(f, role) }); expect(response.status()).toBe(200); expect((await response.json()).course.id).toBe(f.courses.ics.id);
  }
  const start = new Date();
  for (const active of [false, true]) {
    const response = await request.patch(`${f.baseURL}/api/admin/users/${f.accounts.ADMIN_TARGET.id}/status`, { headers: auth(f, 'ADMIN'), data: { isActive: active } }); expect(response.status()).toBe(200);
    const actual = await database(async c => (await c.query('SELECT "isActive" FROM "User" WHERE id=$1', [f.accounts.ADMIN_TARGET.id])).rows[0]); expect(actual.isActive).toBe(active);
  }
  const audits = await database(async c => (await c.query('SELECT action FROM "AuditLog" WHERE "adminId"=$1 AND "targetId"=$2 AND "createdAt">=$3', [f.accounts.ADMIN.id, f.accounts.ADMIN_TARGET.id, start])).rows);
  expect(audits.map(r => r.action)).toEqual(expect.arrayContaining(['ACCOUNT_SUSPENSION', 'ACCOUNT_REACTIVATION']));
  const gradeURL = `${f.baseURL}/api/courses/${f.courses.ics.id}/submissions/grade`, body = { submissionId: f.courses.ics.studentSubmissionId, grade: 17 };
  const deniedBefore = await stateFingerprint();
  for (const role of ['UNASSIGNED_INSTRUCTOR', 'FOREIGN_INSTRUCTOR', 'STUDENT', 'OTHER_STUDENT'] as Role[]) {
    const response = await request.post(gradeURL, { headers: auth(f, role), data: body }); expect(response.status()).toBe(403); errorShape(f, await response.json());
  }
  expect(await stateFingerprint()).toBe(deniedBefore);
  const graded = await request.post(gradeURL, { headers: auth(f, 'INSTRUCTOR'), data: body }); expect(graded.status()).toBe(200);
  const actual = await database(async c => (await c.query('SELECT grade,"isReturned" FROM "StudentSubmission" WHERE id=$1', [body.submissionId])).rows[0]); expect(actual.grade).toBe(17); expect(actual.isReturned).toBe(true);
});

test('AC-004 AC-006 AC-007: supervision DOM, links, forms, data responses and final institute route are read-only', async ({ page, context }) => {
  await context.addCookies([{ name: 'lumina_session', value: f.accounts.SUPER_USER.token, url: f.baseURL }]);
  const loaded: Promise<void>[] = [];
  page.on('response', response => { if (response.url().includes('/api/academic-oversight/')) loaded.push((async () => {
    const body = await response.json(); if (response.url().split('?')[0].endsWith('/courses')) overviewShape(f, body, 'ibe'); else detailShape(f, body, 'ibe', f.courses.ibe);
  })()); });
  await page.goto(`${f.baseURL}/ibe/academic-operations/courses/${f.courses.ibe.id}/supervision`);
  await expect(page).toHaveURL(new RegExp('/ibe/academic-operations/courses/' + f.courses.ibe.id + '/supervision(?:\\?.*)?$'));
  const main = page.getByTestId('course-supervision-readonly'); await expect(main).toBeVisible();
  await expect(main.getByRole('heading', { name: f.courses.ibe.title, exact: true })).toBeVisible();
  await expect(main.locator('form, input, textarea, select, [contenteditable="true"], [data-mutation-control], [data-assessment-execution], button, [role="button"], [role="menuitem"]')).toHaveCount(0);
  for (const link of await main.locator('a').evaluateAll(nodes => nodes.map(n => (n as HTMLAnchorElement).href))) {
    const url = new URL(link); expect(url.origin).toBe(new URL(f.baseURL).origin); expect(url.pathname).toMatch(/^\/ibe\/academic-operations(?:\/|$)/); expect(url.pathname).not.toMatch(/grade|submit|edit|classwork|activit|assessment/i);
  }
  noSensitive(f, await main.innerText()); await Promise.all(loaded);
  // Apply the same DTO contract directly even when this page uses server-rendered data.
  const api = await page.request.get(detail(f, 'ibe', f.courses.ibe.id), { headers: auth(f, 'SUPER_USER') }); expect(api.status()).toBe(200); detailShape(f, await api.json(), 'ibe', f.courses.ibe);
});

