// session resolution, RBAC, Prisma and ownership checks are real. A fail-closed
// external-executor spy detects calls without permitting cloud/local execution.
import {test, after} from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {createRequire} from 'node:module';
import {loadFixture, databaseURL, assertSeeded, stateFingerprint, auditBaseline, assertAuditAppendOnly, controllerEvidence, database} from '../../e2e/controlled/fixture.ts';

const f=loadFixture(),root=process.cwd();process.env.DATABASE_URL=databaseURL();
if(process.env.POSTGRES_URL||process.env.POSTGRES_PRISMA_URL)throw Error('Do not inherit live database alternatives');
let actor='SUPER_USER';const appRequire=createRequire(path.join(root,'apps/web/package.json'));
const {workAsyncStorage}=appRequire('next/dist/server/app-render/work-async-storage.external');
const {workUnitAsyncStorage}=appRequire('next/dist/server/app-render/work-unit-async-storage.external');
const {RequestCookies}=appRequire('next/dist/compiled/@edge-runtime/cookies');
function requestContext(invoke){
